        // Record the swap in our number storage
        self.number.set(amount_in);
        self.benchmarkData.insert(pool_id, amount_in);
        
        Ok(fee)
    }
}

/// Helper methods implementation (non-public)
impl Counter {
    /// Generates a dispute ID from a transaction hash and challenger address
    fn generate_dispute_id(&self, tx_hash: FixedBytes<32>, caller: Address) -> FixedBytes<32> {
        // Simple deterministic ID generation (XOR of tx_hash and caller with timestamp)
        let timestamp_bytes = U256::from(self.vm().block_timestamp()).to_be_bytes::<32>();
        
        let mut result = [0u8; 32];
        let tx_bytes = tx_hash.as_slice();
        let caller_bytes = caller.as_slice();
        
        // XOR the first bytes with tx_hash
        for i in 0..32 {
            result[i] = tx_bytes[i];
        }
        
        // XOR with caller address (20 bytes)
        for i in 0..20 {
            result[i] ^= caller_bytes[i];
        }
        
        // XOR with timestamp
        for i in 0..32 {
            result[i] ^= timestamp_bytes[i];
        }
        
        FixedBytes::from(result)
    }
    
    /// Emits a dispute initiated event
    fn emit_dispute_initiated(&self, dispute_id: FixedBytes<32>, challenger: Address, defender: Address) {
        // Create topic data
