        let mut t2_bytes = [0u8; 32];
        t2_bytes[12..].copy_from_slice(challenger.as_slice());
        let t2 = FixedBytes::from_slice(&t2_bytes);
        
        let mut t3_bytes = [0u8; 32];
        t3_bytes[12..].copy_from_slice(defender.as_slice());
        let t3 = FixedBytes::from_slice(&t3_bytes);
        
        // Create topics array
        let topics = [topic0, dispute_id, t2, t3];
        
        // Empty data array
        let empty_data: [u8; 0] = [];
        
        // Emit the event using VM
        let _ = self.vm().raw_log(&topics, &empty_data);
    }
    
    /// Emits a dispute resolved event
    fn emit_dispute_resolved(&self, dispute_id: FixedBytes<32>) {
        // Create topic data
        let topic0 = self.dispute_resolved_topic();
        
        // Create topics array
        let topics = [topic0, dispute_id];
        
        // Empty data array
        let empty_data: [u8; 0] = [];
        
        // Emit the event using VM
        let _ = self.vm().raw_log(&topics, &empty_data);
    }
    
    /// Returns the topic hash for dispute initiated events
