#[entrypoint]
#[storage]
pub struct GameOfLifeNFT {
    #[borrow]
    pub erc721: Erc721,
}

#[public]
#[inherit(Erc721)]
impl GameOfLifeNFT {
    pub fn mint(&mut self, to: Address, token_id: U256) -> Result<(), Vec<u8>> {
        Ok(self.erc721._mint(to, token_id)?)
    }

    pub fn name(&self) -> Result<String, Vec<u8>> {
        Ok(String::from("Game of Life"))
    }

    pub fn symbol(&self) -> Result<String, Vec<u8>> {
        Ok(String::from("GOL"))
    }

    #[selector(name = "tokenURI")]
    pub fn token_uri(&self, token_id: U256) -> Result<String, Vec<u8>> {
        let seed = token_id.as_limbs()[0];
        let size = 32;
        let generations = 128; // 512 & 1024 out of gas error
        let cell_size = 4;

        let mut svg = String::with_capacity(size * size * 32);
        svg.push_str(
            r#"<svg viewBox="0 0 128 128" xmlns="http://www.w3.org/2000/svg"><style>
            @keyframes p {
                0% {opacity:0}
                20% {opacity:1}
                80% {opacity:1}
                100% {opacity:0}
            }
            @keyframes last {
                0% {opacity:0}
                20% {opacity:1}
                100% {opacity:1}
            }
            rect {fill:#000;opacity:0;animation:p 500ms forwards}
            rect.last {animation:last 500ms forwards}
            </style>"#,
        );

        // Create dynamic grid
        let mut grid = vec![vec![false; size]; size];
        let mut has_cells = false;

        // Initialize first generation from seed
        for y in 0..size {
            for x in 0..size {
                let v = ((x ^ y) + ((x | y) & (size - 1)) + (seed as usize)) & (size - 1);
                if v < size / 3 {
                    grid[y][x] = true;
                    svg.push_str(&format!(
                        r#"<rect x="{}" y="{}" width="{}" height="{}" style="animation-delay:0ms"/>"#,
                        x * cell_size + 1, y * cell_size + 1, cell_size - 1, cell_size - 1
                    ));
                }
            }
        }

        // Compute and render next generations
        for gen in 1..generations {
            let mut next = vec![vec![false; size]; size];
            let mut next_has_cells = false;

            for y in 0..size {
                for x in 0..size {
                    let mut neighbors = 0;
                    for dy in -1..=1 {
                        for dx in -1..=1 {
                            if dx == 0 && dy == 0 {
                                continue;
                            }
                            let nx = (x as i32 + dx).rem_euclid(size as i32) as usize;
                            let ny = (y as i32 + dy).rem_euclid(size as i32) as usize;
                            if grid[ny][nx] {
                                neighbors += 1;
                            }
                        }
                    }
                    next[y][x] = matches!((grid[y][x], neighbors),
                        (true, 2) | (true, 3) | (false, 3));
                    if next[y][x] {
                        next_has_cells = true;
                        let is_last = has_cells && gen == generations - 1;
                        svg.push_str(&format!(
                            r#"<rect x="{}" y="{}" width="{}" height="{}" {} style="animation-delay:{}ms"/>"#,
                            x * cell_size + 1, y * cell_size + 1, cell_size - 1, cell_size - 1,
                            if is_last { "class=\"last\"" } else { "" },
                            gen * 400
                        ));
                    }
                }
            }
            grid = next;
            has_cells = next_has_cells;
        }

        svg.push_str("</svg>");
        Ok(svg)
    }
}

