	('1a91893c-e617-4bd3-9bb8-297965fbca8c', '80eb5de1-6595-42fe-80a8-2f292d2764ce', 'tuck-counter-contract', 'extern crate alloc;

/// Import items from the SDK. The prelude contains common traits and macros.
use stylus_sdk::{
    alloy_primitives::U256,
    alloy_primitives::Address,
    call::{call, Call},
    msg::{self},
    prelude::*
};

// Define some persistent storage using the Solidity ABI.
// Counter will be the entrypoint.
sol_storage! {
    #[entrypoint]
    pub struct Counter {
        uint256 number;
    }
}

/// Declare that Counter is a contract with the following external methods.
#[public]
impl Counter {
    /// Gets the number from storage.
    pub fn number(&self) -> U256 {
        self.number.get()
    }

    /// Sets a number in storage to a user-specified value.
    pub fn set_number(&mut self, new_number: U256) {
        self.number.set(new_number);
    }

    /// Sets a number in storage to a user-specified value.
    pub fn mul_number(&mut self, new_number: U256) {
        self.number.set(new_number * self.number.get());
    }

    /// Sets a number in storage to a user-specified value.
    pub fn add_number(&mut self, new_number: U256) {
        self.number.set(new_number + self.number.get());
    }

    /// Increments `number` and updates its value in storage.
    pub fn increment(&mut self) {
        let number = self.number.get();
        self.set_number(number + U256::from(1));
    }

    #[payable]
    pub fn send_via_call(&mut self, to: Address) -> Result<(), Vec<u8>> {
        call(Call::new_in(self).value(msg::value()), to, &[])?;
        Ok(())
    }
}', '2025-02-07 11:05:23.027649+00', '2025-02-07 11:13:29.103+00', 'A foundational smart contract demonstrating state management and basic interactions. Perfect starting point for learning Stylus development with a simple yet practical example.', '{}', '2025-08-13 16:47:53.589535+00', false, NULL, 0, NULL, 'manual', '{}', NULL, '{}'),
