	('f6140c41-05e3-4545-8932-4e2acf36d7c2', '900c061e-75e6-4179-a838-d0c8d993d548', 'depin-energy', 'use stylus_sdk::{alloy_primitives::U256, prelude::*};

// Mock Oracle (replace with Chainlink later)
struct EnergyOracle;

impl EnergyOracle {
    fn verify_delivery(kwh: U256) -> bool {
        // In production, this would call an oracle
        kwh > U256::ZERO
    }
}

// Energy Offer Types
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum OfferType {
    Sell,
    Buy,
}

// Main Contract
sol_storage! {
    pub struct EnergyTrading {
        // Track registered meters (IoT devices)
        mapping(address => bool) registered_meters;
        
        // Active energy offers
        mapping(uint256 => EnergyOffer) offers;
        uint256 offer_count;
        
        // User balances (in wei)
        mapping(address => U256) balances;
        
        // User reputation (penalize bad actors)
        mapping(address => U256) reputation;
    }

    // Energy Offer Struct
    pub struct EnergyOffer {
        offer_type: OfferType,
        seller: address,
        buyer: Option<address>,
        kwh: U256,
        price_per_kwh: U256,
        fulfilled: bool,
    }
}

// External functions (ABI)
#[external]
impl EnergyTrading {
    // Register a new IoT meter
    pub fn register_meter(&mut self) -> Result<(), Vec<u8>> {
        let sender = msg::sender();
        self.registered_meters.setter(sender).set(true);
        Ok(())
    }

    // Post a new energy offer (sell/buy)
    pub fn post_offer(
        &mut self,
        offer_type: OfferType,
        kwh: U256,
        price_per_kwh: U256,
    ) -> Result<(), Vec<u8>> {
        let sender = msg::sender();
        require!(self.registered_meters.get(sender), "Meter not registered");

        let offer_id = self.offer_count.get();
        self.offers.setter(offer_id).set(EnergyOffer {
            offer_type,
            seller: sender,
            buyer: None,
            kwh,
            price_per_kwh,
            fulfilled: false,
        });

        self.offer_count.set(offer_id + U256::ONE);
        Ok(())
    }

    // Execute a trade (buyer accepts offer)
    pub fn execute_trade(&mut self, offer_id: U256) -> Result<(), Vec<u8>> {
        let mut offer = self.offers.get(offer_id);
        require!(!offer.fulfilled, "Offer already fulfilled");

        let buyer = msg::sender();
        let total_cost = offer.kwh * offer.price_per_kwh;

        // Check buyer balance
        require!(
            self.balances.get(buyer) >= total_cost,
            "Insufficient balance"
        );

        // Verify energy delivery (mock oracle)
        require!(
            EnergyOracle::verify_delivery(offer.kwh),
            "Delivery not confirmed"
        );

        // Transfer funds
        self.balances.setter(buyer).set(self.balances.get(buyer) - total_cost);
        self.balances.setter(offer.seller).set(self.balances.get(offer.seller) + total_cost);

        // Update offer
        offer.buyer = Some(buyer);
        offer.fulfilled = true;
        self.offers.setter(offer_id).set(offer);

        Ok(())
    }
}', '2025-04-03 16:53:03.98777+00', '2025-04-03 16:55:35.715+00', 'Decentralized Physical Infrastructure (DePIN) for Energy Trading', '{}', '2025-08-13 16:47:53.589535+00', false, NULL, 0, NULL, 'manual', '{}', NULL, '{}'),
