	('ff147e78-6caa-4280-a3ba-33a834f6e268', '72349ca4-b81a-4469-8ebd-184b5723fff9', 'ArbitrumStylusTriangularArbitrage.rs', '#![cfg_attr(not(feature = "export-abi"), no_main)]
extern crate alloc;

use alloc::{format, string::String, vec, vec::Vec};
use stylus_sdk::{
    address,
    abi::Bytes,
    alloy_primitives::{Address, U256},
    alloy_sol_types::{sol, SolCall},
    call::RawCall,
    crypto::keccak256,
    evm, msg,
    prelude::*,
};

// Interface for Uniswap V2 pairs
sol! {
    interface IUniswapV2Pair {
        function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
        function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
        function token0() external view returns (address);
        function token1() external view returns (address);
    }
}

// Interface for Uniswap V3 flash
sol! {
    interface IUniswapV3Pool {
        function flash(
            address recipient,
            uint256 amount0,
            uint256 amount1,
            bytes calldata data
        ) external;
        function token0() external view returns (address);
        function token1() external view returns (address);
    }
}

// ERC20 interface for token operations
sol! {
    interface IERC20 {
        function balanceOf(address account) external view returns (uint256);
        function transfer(address recipient, uint256 amount) external returns (bool);
        function approve(address spender, uint256 amount) external returns (bool);
    }
}

// Router interfaces for various DEXes
sol! {
    interface IUniswapV2Router {
        function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts);
        function swapExactTokensForTokens(
            uint amountIn,
            uint amountOutMin,
            address[] calldata path,
            address to,
            uint deadline
        ) external returns (uint[] memory amounts);
    }

    interface IUniswapV3Router {
        struct ExactInputSingleParams {
            address tokenIn;
            address tokenOut;
            uint24 fee;
            address recipient;
            uint256 deadline;
            uint256 amountIn;
            uint256 amountOutMinimum;
            uint160 sqrtPriceLimitX96;
        }

        function exactInputSingle(ExactInputSingleParams calldata params) external returns (uint256 amountOut);
    }
}

// Flash callback interface
sol! {
    interface IFlashCallback {
        function uniswapV2Call(address sender, uint amount0, uint amount1, bytes calldata data) external;
        function uniswapV3FlashCallback(uint256 fee0, uint256 fee1, bytes calldata data) external;
    }
}

// Storage for our contract
#[solidity_storage]
#[derive(Debug)]
pub struct ArbitrageFlashSwap {
    owner: StorageAddress,
    fee_numerator: StorageU256,
    fee_denominator: StorageU256,
    uniswap_v2_router: StorageAddress,
    uniswap_v3_router: StorageAddress,
    sushi_router: StorageAddress,
    pancake_router: StorageAddress,
    quickswap_router: StorageAddress,
}

// Custom struct for flash swap data
struct FlashSwapData {
    borrowing_pool: Address,
    token_borrowed: Address,
    amount_borrowed: U256,
    route_dex: Vec<u8>,  // 0: UniV2, 1: UniV3, 2: Sushi, 3: Pancake, 4: Quickswap
    route_tokens: Vec<Address>,
    route_fees: Vec<u32>, // For Uniswap V3 (fee tiers)
}

// Implementation of the contract
#[external]
impl ArbitrageFlashSwap {

    pub fn constructor(&mut self) {
        // Set owner as contract deployer
        self.owner.set(msg::sender());

        // Default fee: 0.5%
        self.fee_numerator.set(U256::from(995));
        self.fee_denominator.set(U256::from(1000));

        // Initialize with Arbitrum DEX router addresses
        self.uniswap_v2_router = Address::from_slice(&hex_literal::hex!(
            "7a250d5630B4cF539739dF2C5dAcb4c659F2488D" // Uniswap V2 router on Arbitrum
        ));
        self.uniswap_v3_router = Address::from_slice(&hex_literal::hex!(
            "E592427A0AEce92De3Edee1F18E0157C05861564" // Uniswap V3 router on Arbitrum
        ));
        self.sushi_router = Address::from_slice(&hex_literal::hex!(
            "1b02dA8Cb0d097eB8D57A175b88c7D8b47997506" // Sushiswap router on Arbitrum
        ));
        self.pancake_router = Address::from_slice(&hex_literal::hex!(
            "1b02dA8Cb0d097eB8D57A175b88c7D8b47997506" // Pancakeswap router on Arbitrum
        ));
        self.quickswap_router = Address::from_slice(&hex_literal::hex!(
            "a5E0829CaCEd8fFDD4De3c43696c57F7D7A678ff" // Quickswap router on Arbitrum
        ));
    }

    // Owner can update DEX router addresses
    #[payable]
    pub fn update_router_address(&mut self, dex_type: u8, new_address: Address) -> Result<bool, Vec<u8>> {
        self.only_owner()?;

        match dex_type {
            0 => self.uniswap_v2_router = new_address,
            1 => self.uniswap_v3_router = new_address,
            2 => self.sushi_router = new_address,
            3 => self.pancake_router = new_address,
            4 => self.quickswap_router = new_address,
            _ => return Err("Invalid DEX type".into()),
        }

        Ok(true)
    }

    // Update fee percentage
    #[payable]
    pub fn update_fee(&mut self, numerator: U256, denominator: U256) -> Result<bool, Vec<u8>> {
        self.only_owner()?;

        if denominator == U256::ZERO {
            return Err("Denominator cannot be zero".into());
        }

        if numerator > denominator {
            return Err("Fee cannot be greater than 100%".into());
        }

        self.fee_numerator = numerator;
        self.fee_denominator = denominator;

        Ok(true)
    }

    // Withdraw tokens from contract
    #[payable]
    pub fn withdraw_tokens(&mut self, token: Address, amount: U256) -> Result<bool, Vec<u8>> {
        self.only_owner()?;

        let transfer_call = IERC20::transferCall {
            recipient: self.owner,
            amount,
        };

        let result = unsafe { RawCall::call_successfully(token, transfer_call) }

        match result {
            Ok(_) => Ok(true),
            Err(_) => Err("Token transfer failed".into()),
        }
    }

    // Main function to start a flash swap arbitrage
    #[payable]
    pub fn start_flash_swap(
        &mut self,
        borrowing_pool: Address,
        is_v3_pool: bool,
        token_borrow_idx: u8,
        amount_to_borrow: U256,
        route_dex: Vec<u8>,
        route_tokens: Vec<Address>,
        route_fees: Vec<u32>,
    ) -> Result<bool, Vec<u8>> {
        // Validate inputs
        if route_tokens.len() < 2 {
            return Err("At least 2 tokens required for route".into());
        }

        if route_dex.len() != route_tokens.len() - 1 {
            return Err("DEX route count mismatch".into());
        }

        let token0: Address;
        let token1: Address;

        // Get tokens from the pool
        if is_v3_pool {
            let token0_call = IUniswapV3Pool::token0Call {};
            let token1_call = IUniswapV3Pool::token1Call {};

            token0 = unsafe { borrowing_pool.call(token0_call) }?;
            token1 = unsafe { borrowing_pool.call(token1_call) }?;
        } else {
            let token0_call = IUniswapV2Pair::token0Call {};
            let token1_call = IUniswapV2Pair::token1Call {};

            token0 = unsafe { borrowing_pool.call(token0_call) }?;
            token1 = unsafe { borrowing_pool.call(token1_call) }?;
        }

        // Determine which token to borrow
        let borrowed_token = if token_borrow_idx == 0 { token0 } else { token1 };

        // Ensure the borrowed token matches the first token in route
        if borrowed_token != route_tokens[0] {
            return Err("Borrowed token must match first token in route".into());
        }

        // Prepare flash swap data for callback
        let flash_data = FlashSwapData {
            borrowing_pool,
            token_borrowed: borrowed_token,
            amount_borrowed: amount_to_borrow,
            route_dex,
            route_tokens,
            route_fees,
        };

        // Encode flash data for the callback
        let encoded_data = self.encode_flash_data(&flash_data);

        // Execute the flash swap
        if is_v3_pool {
            // Uniswap V3 flash loan
            let amount0 = if token_borrow_idx == 0 { amount_to_borrow } else { U256::ZERO };
            let amount1 = if token_borrow_idx == 1 { amount_to_borrow } else { U256::ZERO };

            let flash_call = IUniswapV3Pool::flashCall {
                recipient: address(),
                amount0,
                amount1,
                data: alloy_sol_types::Bytes::from(encoded_data),
            };

            unsafe { borrowing_pool.call(flash_call) }?;
        } else {
            // Uniswap V2 flash swap
            let amount0_out = if token_borrow_idx == 0 { amount_to_borrow } else { U256::ZERO };
            let amount1_out = if token_borrow_idx == 1 { amount_to_borrow } else { U256::ZERO };

            let swap_call = IUniswapV2Pair::swapCall {
                amount0Out: amount0_out,
                amount1Out: amount1_out,
                to: address(),
                data: Bytes::from(encoded_data),
            };

            unsafe { RawCall::call_successfully(borrowing_pool, swap_call) }?;
        }

        Ok(true)
    }

    // UniswapV2 flash swap callback
    #[payable]
    pub fn uniswap_v2_call(
        &mut self,
        _sender: Address,
        amount0: U256,
        amount1: U256,
        data: Bytes
    ) -> Result<(), Vec<u8>> {
        // Ensure caller is a valid pair
        let token0_call = IUniswapV2Pair::token0Call {};
        let _ = unsafe { msg::sender().call(token0_call) }
            .map_err(|_| "Caller is not a Uniswap V2 pair")?;

        // Decode flash data
        let flash_data = self.decode_flash_data(&data.0)?;

        // Validate the caller is the borrowing pool
        if msg::sender() != flash_data.borrowing_pool {
            return Err("Unauthorized caller".into());
        }

        // Determine borrowed amount
        let borrowed_amount = if amount0 > U256::ZERO { amount0 } else { amount1 };

        // Execute arbitrage swaps
        let profit = self.execute_arbitrage_route(&flash_data)?;

        // Calculate repayment amount (borrowed + fee)
        let repayment_amount = borrowed_amount * self.fee_denominator / self.fee_numerator;

        // Check if profitable
        if profit <= repayment_amount {
            return Err("Arbitrage not profitable".into());
        }

        // Repay the flash swap
        let transfer_call = IERC20::transferCall {
            recipient: flash_data.borrowing_pool,
            amount: repayment_amount,
        };

        unsafe { flash_data.token_borrowed.call(transfer_call) }?;

        Ok(())
    }

    // UniswapV3 flash callback
    #[payable]
    pub fn uniswap_v3_flash_callback(
        &mut self,
        fee0: U256,
        fee1: U256,
        data: Bytes
    ) -> Result<(), Vec<u8>> {
        // Decode flash data
        let flash_data = self.decode_flash_data(&data.0)?;

        // Validate the caller is the borrowing pool
        if msg::sender() != flash_data.borrowing_pool {
            return Err("Unauthorized caller".into());
        }

        // Determine fee
        let fee = if fee0 > U256::ZERO { fee0 } else { fee1 };

        // Execute arbitrage swaps
        let profit = self.execute_arbitrage_route(&flash_data)?;

        // Calculate repayment amount (borrowed + fee)
        let repayment_amount = flash_data.amount_borrowed + fee;

        // Check if profitable
        if profit <= repayment_amount {
            return Err("Arbitrage not profitable".into());
        }

        // Repay the flash loan
        let transfer_call = IERC20::transferCall {
            recipient: flash_data.borrowing_pool,
            amount: repayment_amount,
        };

        unsafe { flash_data.token_borrowed.call(transfer_call) }?;

        Ok(())
    }

    // Helper functions

    // Execute arbitrage route through multiple DEXes
    fn execute_arbitrage_route(&self, flash_data: &FlashSwapData) -> Result<U256, Vec<u8>> {
        let mut current_amount = flash_data.amount_borrowed;
        let mut current_token = flash_data.token_borrowed;

        // Process each swap in the route
        for i in 0..flash_data.route_dex.len() {
            let from_token = current_token;
            let to_token = flash_data.route_tokens[i + 1];

            // Approve router to spend token
            let router = self.get_router_by_type(flash_data.route_dex[i])?;

            let approve_call = IERC20::approveCall {
                spender: router,
                amount: current_amount,
            };

            unsafe { from_token.call(approve_call) }?;

            // Execute swap based on DEX type
            match flash_data.route_dex[i] {
                1 => {
                    // Uniswap V3
                    if i >= flash_data.route_fees.len() {
                        return Err("Missing fee tier for Uniswap V3 swap".into());
                    }

                    let params = IUniswapV3Router::ExactInputSingleParams {
                        tokenIn: from_token,
                        tokenOut: to_token,
                        fee: flash_data.route_fees[i].into(),
                        recipient: address(),
                        deadline: block_timestamp() + 300, // 5 minutes deadline
                        amountIn: current_amount,
                        amountOutMinimum: U256::ZERO, // No slippage protection for simplicity
                        sqrtPriceLimitX96: 0.into(),
                    };

                    let exact_input_call = IUniswapV3Router::exactInputSingleCall { params };

                    current_amount = unsafe { router.call(exact_input_call) }?;
                },
                _ => {
                    // Uniswap V2-compatible routers (V2, Sushi, Pancake, Quickswap)
                    let mut path = Vec::new();
                    path.push(from_token);
                    path.push(to_token);

                    let swap_call = IUniswapV2Router::swapExactTokensForTokensCall {
                        amountIn: current_amount,
                        amountOutMin: U256::ZERO, // No slippage protection for simplicity
                        path: path.into(),
                        to: address(),
                        deadline: block_timestamp() + 300, // 5 minutes deadline
                    };

                    let amounts = unsafe { router.call(swap_call) }?;
                    current_amount = amounts[amounts.len() - 1];
                }
            }

            current_token = to_token;
        }

        // Ensure final token is the same as borrowed token (for repayment)
        if current_token != flash_data.token_borrowed {
            return Err("Final token must match borrowed token".into());
        }

        Ok(current_amount)
    }

    fn get_router_by_type(&self, dex_type: u8) -> Result<Address, Vec<u8>> {
        match dex_type {
            0 => Ok(self.uniswap_v2_router),
            1 => Ok(self.uniswap_v3_router),
            2 => Ok(self.sushi_router),
            3 => Ok(self.pancake_router),
            4 => Ok(self.quickswap_router),
            _ => Err("Invalid DEX type".into()),
        }
    }

    fn only_owner(&self) -> Result<(), Vec<u8>> {
        if msg::sender() != self.owner {
            return Err("Caller is not the owner".into());
        }
        Ok(())
    }

    // Encode/decode flash data for callbacks
    fn encode_flash_data(&self, data: &FlashSwapData) -> Vec<u8> {
        let mut encoded = Vec::new();

        // Pack borrowing pool address
        encoded.extend_from_slice(data.borrowing_pool.as_slice());

        // Pack borrowed token address
        encoded.extend_from_slice(data.token_borrowed.as_slice());

        // Pack borrowed amount (32 bytes)
        let mut amount_bytes = [0u8; 32];
        amount_bytes.copy_from_slice(&data.amount_borrowed.to_be_bytes::<32>());
        encoded.extend_from_slice(&amount_bytes);

        // Pack route DEX types length and values
        encoded.push(data.route_dex.len() as u8);
        encoded.extend_from_slice(&data.route_dex);

        // Pack route tokens length and values
        encoded.push(data.route_tokens.len() as u8);
        for token in &data.route_tokens {
            encoded.extend_from_slice(token.as_slice());
        }

        // Pack route fees length and values
        encoded.push(data.route_fees.len() as u8);
        for &fee in &data.route_fees {
            encoded.extend_from_slice(&fee.to_be_bytes());
        }

        encoded
    }

    fn decode_flash_data(&self, encoded: &[u8]) -> Result<FlashSwapData, Vec<u8>> {
        if encoded.len() < 20 + 20 + 32 + 1 {
            return Err("Invalid encoded data length".into());
        }

        let mut index = 0;

        // Decode borrowing pool address
        let borrowing_pool = Address::from_slice(&encoded[index..index+20]);
        index += 20;

        // Decode borrowed token address
        let token_borrowed = Address::from_slice(&encoded[index..index+20]);
        index += 20;

        // Decode borrowed amount
        let amount_borrowed = U256::from_be_slice(&encoded[index..index+32])
        index += 32;

        // Decode route DEX types
        let route_dex_len = encoded[index] as usize;
        index += 1;
        if index + route_dex_len > encoded.len() {
            return Err("Invalid encoded data".into());
        }
        let route_dex = encoded[index..index+route_dex_len].to_vec();
        index += route_dex_len;

        // Decode route tokens
        let route_tokens_len = encoded[index] as usize;
        index += 1;
        let mut route_tokens = Vec::with_capacity(route_tokens_len);
        for _ in 0..route_tokens_len {
            if index + 20 > encoded.len() {
                return Err("Invalid encoded data".into());
            }
            route_tokens.push(Address::from_slice(&encoded[index..index+20]));
            index += 20;
        }

        // Decode route fees
        let route_fees_len = encoded[index] as usize;
        index += 1;
        let mut route_fees = Vec::with_capacity(route_fees_len);
        for _ in 0..route_fees_len {
            if index + 4 > encoded.len() {
                return Err("Invalid encoded data".into());
            }
            let fee_bytes = [
                encoded[index],
                encoded[index+1],
                encoded[index+2],
                encoded[index+3],
            ];
            route_fees.push(u32::from_be_bytes(fee_bytes));
            index += 4;
        }

        Ok(FlashSwapData {
            borrowing_pool,
            token_borrowed,
            amount_borrowed,
            route_dex,
            route_tokens,
            route_fees,
        })
    }

    // View functions

    // Calculate expected profit for a route
    pub fn calculate_expected_profit(
        &self,
        amount_to_borrow: U256,
        route_dex: Vec<u8>,
        route_tokens: Vec<Address>,
        route_fees: Vec<u32>,
    ) -> Result<U256, Vec<u8>> {
        if route_tokens.len() < 2 {
            return Err("At least 2 tokens required for route".into());
        }

        if route_dex.len() != route_tokens.len() - 1 {
            return Err("DEX route count mismatch".into());
        }

        let mut current_amount = amount_to_borrow;

        // Simulate each swap in the route
        for i in 0..route_dex.len() {
            let from_token = route_tokens[i];
            let to_token = route_tokens[i + 1];
            let router = self.get_router_by_type(route_dex[i])?;

            match route_dex[i] {
                1 => {
                    // Uniswap V3 - simplified estimation
                    // In reality, would need to query pool for exact quote
                    let fee_factor = U256::from(1000000 - route_fees[i]);
                    current_amount = current_amount * fee_factor / U256::from(1000000);
                },
                _ => {
                    // Uniswap V2-compatible routers - use getAmountsOut
                    let mut path = Vec::new();
                    path.push(from_token);
                    path.push(to_token);

                    let get_amounts_call = IUniswapV2Router::getAmountsOutCall {
                        amountIn: current_amount,
                        path: path.into(),
                    };

                    let amounts = unsafe { router.call(get_amounts_call) }?;
                    current_amount = amounts[amounts.len() - 1];
                }
            }
        }

        // Calculate repayment amount
        let repayment_amount = amount_to_borrow * self.fee_denominator / self.fee_numerator;

        // Calculate expected profit
        if current_amount > repayment_amount {
            Ok(current_amount - repayment_amount)
        } else {
            Ok(U256::ZERO)
        }
    }

    // Getter functions
    pub fn get_owner(&self) -> Result<Address, Vec<u8>> {
        Ok(self.owner)
    }

    pub fn get_fee_parameters(&self) -> Result<(U256, U256), Vec<u8>> {
        Ok((self.fee_numerator, self.fee_denominator))
    }

    pub fn get_router_address(&self, dex_type: u8) -> Result<Address, Vec<u8>> {
        self.get_router_by_type(dex_type)
    }
    fn execute_arbitrage_route(&self, flash_data: &FlashSwapData) -> Result<U256, Vec<u8>> {
        // Implementation
        self.get_router_by_type(flash_data.route_dex[0])?;
        let mut current_amount = flash_data.amount_borrowed;
        let mut current_token = flash_data.token_borrowed;
        for i in 0..flash_data.route_dex.len() {
            let router = self.get_router_by_type(flash_data.route_dex[i])?;
            let to_token = flash_data.route_tokens[i + 1];
            let fee_factor = U256::from(1000000 - flash_data.route_fees[i]);
            current_amount = current_amount * fee_factor / U256::from(1000000);
        }
    }
    fn get_router_by_type(&self, dex_type: u8) -> Result<Address, Vec<u8>> {
        match dex_type {
            0 => Ok(self.uniswap_v2_router),
            1 => Ok(self.uniswap_v3_router),
            2 => Ok(self.sushi_router),
            3 => Ok(self.pancake_router),
            4 => Ok(self.quickswap_router),
            _ => Err("Invalid DEX type".into()),
        }
    }
    fn only_owner(&self) -> Result<(), Vec<u8>> {
        if msg::sender() != self.owner {
            return Err("Caller is not the owner".into());
        }
        Ok(())
    }
    // Encode/decode flash data for callbacks
    fn encode_flash_data_callback(&self, data: &FlashSwapData) -> Vec<u8> {
        self.encode_flash_data(data)
    }

    fn decode_flash_data_callback(&self, encoded: &[u8]) -> Result<FlashSwapData, Vec<u8>> {
        self.decode_flash_data(encoded)
    }
