        "PODRPS".to_string()
    }

    pub fn name(&self) -> String {
        "Proof-of-Defeat Rock Paper Scissor NFT".to_string()
    }

    pub fn description(&self) -> String {
        "Your ultimate enemy in Rock-Paper-Scissors.".to_string()
    }

    pub fn balance_of(&self, owner: Address) -> U256 {
        if owner == self.owner.get() {
            U256::from(1)
        } else {
            U256::from(0)
        }
    }

    pub fn owner_of(&self, token_id: U256) -> Result<Address, Vec<u8>> {
        if token_id != U256::from(1) {
            return Err("Invalid token ID".as_bytes().to_vec());
        }

        let owner = self.owner.get();

        if owner == Address::ZERO {
            return Err("Token not minted".as_bytes().to_vec());
        }

        Ok(owner)
    }

    pub fn choose_move(&self, player_move: U32) -> U32 {
        // Default to a random move
        let (random_idx, _) = Self::pseudo_random(self.rng_seed.get().to::<u32>());
        U32::from(random_idx % 3)
    }

    pub fn update_q_value(&mut self, player_move: U32, reward: I32) {
        // Calculate state key based on current history
        let state_key = 0u32; // Simplified state handling
        
        // Update Q-value for the current state-action pair
        self.q_table
            .setter(state_key)
            .setter(player_move.to::<u32>())
            .set(reward);
            
        // Update history
        let fifth = I32::try_from(player_move).unwrap();
        self.history.setter(4).set(fifth);
    }

    pub fn play(&mut self, player_move: U32) -> (U32, I32) {
        let ai_move = self.choose_move(player_move);
        let ai_move_enum = Move::from_index(ai_move.to());
        let player_move_enum = Move::from_index(player_move.to());

        let reward = if ai_move_enum.beats(&player_move_enum) {
            I32::try_from(1).unwrap()
        } else if player_move_enum.beats(&ai_move_enum) {
            I32::try_from(-1).unwrap()
        } else {
            I32::try_from(0).unwrap()
        };

        self.update_q_value(player_move, reward);

        (ai_move, reward)
    }

    pub fn get_history(&self) -> [I32; HISTORY_SIZE] {
        [
            self.history.get(0),
            self.history.get(1),
            self.history.get(2),
            self.history.get(3),
            self.history.get(4),
        ]
    }

    #[selector(name = "tokenURI")]
    pub fn token_uri(&self, _token_id: U256) -> String {
        let mut uri = String::new();
        write!(
            uri,
            "https://api.dicebear.com/9.x/croodles/svg?seed={}{}",
            self.owner.get(),
            self.balance_of(self.owner.get())
        )
        .unwrap();
        uri
    }

    pub fn get_q_value(&self, state: u32, action: u32) -> I32 {
        self.q_table.get(state).get(action)
    }
}

impl Contract {
    fn pseudo_random(seed: u32) -> (u32, u32) {
        let a: u32 = 1664525;
        let c: u32 = 1013904223;
        let new_seed = seed.wrapping_mul(a).wrapping_add(c);
        let random = new_seed % 100;
        (random, new_seed)
    }
