extern crate alloc;

use stylus_sdk::{
    alloy_primitives::{Address, I32, U32},
    prelude::*,
};
use stylus_sdk::{alloy_sol_types::sol, evm};
use stylus_sdk::storage::{StorageAddress, StorageArray, StorageI32, StorageMap, StorageU32};

const HISTORY_SIZE: usize = 5;

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Move {
    Rock,
    Paper,
    Scissors,
}

impl Move {
    pub fn from_index(idx: u32) -> Self {
        match idx {
            0 => Move::Rock,
            1 => Move::Paper,
            _ => Move::Scissors,
        }
    }

    pub fn to_index(&self) -> u32 {
        match self {
            Move::Rock => 0,
            Move::Paper => 1,
            Move::Scissors => 2,
        }
    }

    pub fn beats(&self, other: &Move) -> bool {
        matches!(
            (self, other),
            (Move::Rock, Move::Scissors)
                | (Move::Paper, Move::Rock)
                | (Move::Scissors, Move::Paper)
        )
    }
}

sol! {
    event TrainingCompleted();
}

#[entrypoint]
#[storage]
pub struct Contract {
    owner: StorageAddress,
    q_table: StorageMap<u32, StorageMap<u32, StorageI32>>,
    history: StorageMap<u32, StorageI32>,
    epsilon: StorageU32,
    alpha: StorageU32,
    gamma: StorageU32,
    rng_seed: StorageU32,
}

#[public]
impl Contract {
    pub fn mint(&mut self, to: Address) {
        self.owner.set(to);
        self.rng_seed.set(U32::from(42));
        self.epsilon.set(U32::from(20));  // 20% exploration
        self.alpha.set(U32::from(10));    // Learning rate 0.1
        self.gamma.set(U32::from(90));    // Discount factor 0.9
        
        // Initialize history with default moves (Rock)
        for i in 0..HISTORY_SIZE {
            self.history.setter(i as u32).set(I32::from(0));
        }
    }

    pub fn choose_move(&self, player_move: U32) -> U32 {
        // Get current state from history
        let state_key = Self::encode_state(
            self.history.get(0).as_u32(),
            self.history.get(1).as_u32(),
            self.history.get(2).as_u32(),
            self.history.get(3).as_u32(),
            player_move.to::<u32>(),
        );

        // Handle exploration vs exploitation
        let (rand_val, _new_seed) = Self::pseudo_random(self.rng_seed.get().to::<u32>());
        
        if rand_val < self.epsilon.get().to::<u32>() {
            let (random_idx, _) = Self::pseudo_random(self.rng_seed.get().to::<u32>());
            return U32::from(random_idx % 3);
        }

        // Exploit: choose best action based on Q-values
        let q_values = self.q_table.get(state_key);
        let mut best_action = 0;
        let mut best_val = q_values.get(0);

        for i in 1..3 {
            if q_values.get(i) > best_val {
                best_val = q_values.get(i);
                best_action = i as u32;
            }
        }

        U32::from(best_action)
    }

    pub fn update_q_value(&mut self, player_move: U32, reward: I32) {
        let state_key = Self::encode_state(
            self.history.get(0).as_u32(),
            self.history.get(1).as_u32(),
            self.history.get(2).as_u32(),
            self.history.get(3).as_u32(),
            self.history.get(4).as_u32(),
        );

        let q_values = self.q_table.get(state_key);
        
        // Find max Q-value for next state
        let mut max_next_q = 0;
        for i in 0..3 {
            if q_values.get(i).as_i32() > max_next_q {
                max_next_q = q_values.get(i).as_i32();
            }
        }

        let action_idx = player_move.to::<u32>();
        let alpha = self.alpha.get().to::<i32>();
        let gamma = self.gamma.get().to::<i32>();

        // Q-learning update formula
        let delta = reward.as_i32() * 100 + (gamma * max_next_q) / 100 - q_values.get(action_idx).as_i32();
        let new_q_value = I32::try_from(q_values.get(action_idx).as_i32() + (alpha * delta) / 100).unwrap();
        
        // Update Q-value
        self.q_table
            .setter(state_key)
            .setter(action_idx)
            .set(new_q_value);

        // Update history
        self.update_history(player_move);
    }

    pub fn play(&mut self, player_move: U32) -> (U32, I32) {
        let ai_move = self.choose_move(player_move);
        let ai_move_enum = Move::from_index(ai_move.to());
        let player_move_enum = Move::from_index(player_move.to());

        let reward = if ai_move_enum.beats(&player_move_enum) {
            I32::try_from(1).unwrap()
        } else if player_move_enum.beats(&ai_move_enum) {
            I32::try_from(-1).unwrap()
        } else {
            I32::try_from(0).unwrap()
        };

        self.update_q_value(player_move, reward);
        (ai_move, reward)
    }

    // Helper functions
    fn update_history(&mut self, new_move: U32) {
        // Shift history and add new move
        for i in 0..(HISTORY_SIZE - 1) {
            let next_value = self.history.get(i + 1);
            self.history.setter(i).set(next_value);
        }
        self.history.setter(HISTORY_SIZE as u32 - 1).set(I32::try_from(new_move.to::<u32>()).unwrap());
    }

    fn encode_state(first: u32, second: u32, third: u32, fourth: u32, fifth: u32) -> u32 {
        let mut state = 0u32;
        state += first * 3u32.pow(0);
        state += second * 3u32.pow(1);
        state += third * 3u32.pow(2);
        state += fourth * 3u32.pow(3);
        state += fifth * 3u32.pow(4);
        state
    }

    fn pseudo_random(seed: u32) -> (u32, u32) {
        let a: u32 = 1664525;
        let c: u32 = 1013904223;
        let new_seed = seed.wrapping_mul(a).wrapping_add(c);
        let random = new_seed % 100;
        (random, new_seed)
    }
