        let mut state = 0u32;
        state += first * 3u32.pow(0);
        state += second * 3u32.pow(1);
        state += third * 3u32.pow(2);
        state += fourth * 3u32.pow(3);
        state += fifth * 3u32.pow(4);
        state
    }

    pub fn get_q_value(&self, state: u32, action: u32) -> I32 {
