#![cfg_attr(not(any(feature = "export-abi", test)), no_main)]
extern crate alloc;

use alloc::{string::String, vec::Vec};
use alloy_primitives::{Address, U256};
use stylus_sdk::{
    evm,
    msg,
    prelude::*,
};

mod erc721;
use crate::erc721::{Erc721, Erc721Params, Erc721Error};

// Define the parameters for the ERC721 token
struct TokenMasterParams;
impl Erc721Params for TokenMasterParams {
    const NAME: &''static str = "TokenMaster";
    const SYMBOL: &''static str = "TKM";

    fn token_uri(token_id: U256) -> String {
        format!("https://tokenmaster.com/token/{}", token_id)
    }
}

#[derive(Clone)]
pub struct Occasion {
    id: U256,
    name: String,
    cost: U256,
    tickets: U256,
    max_tickets: U256,
    date: String,
    time: String,
    location: String,
}

sol_storage! {
    #[entrypoint]
    pub struct TokenMaster {
        #[borrow]
        Erc721<TokenMasterParams> erc721;
        
        // Contract owner
        address owner;
        
        // Counters
        uint256 total_occasions;
        
        // Mappings
        mapping(uint256 => Occasion) occasions;
        mapping(uint256 => mapping(address => bool)) has_bought;
        mapping(uint256 => mapping(uint256 => address)) seat_taken;
        mapping(uint256 => Vec<U256>) seats_taken;
    }
}

// Events
sol! {
    event OccasionListed(uint256 indexed id, string name, uint256 cost, uint256 tickets);
    event TicketMinted(uint256 indexed id, uint256 seat, address buyer);
    
    error InvalidId();
    error InsufficientPayment();
    error SeatTaken();
    error InvalidSeat();
    error Unauthorized();
}

#[external]
impl TokenMaster {
    pub fn constructor() -> Self {
        let mut contract = Self::default();
        contract.owner.set(msg::sender());
        contract
    }
    
    #[payable]
    pub fn list(
        &mut self,
        name: String,
        cost: U256,
        max_tickets: U256,
        date: String,
        time: String,
        location: String,
    ) -> Result<(), Error> {
        if msg::sender() != self.owner.get() {
            return Err(Error::Unauthorized);
        }

        let total_occasions = self.total_occasions.get() + U256::from(1);
        self.total_occasions.set(total_occasions);

        let occasion = Occasion {
            id: total_occasions,
            name: name.clone(),
            cost,
            tickets: max_tickets,
            max_tickets,
            date,
            time,
            location,
        };

        self.occasions.insert(total_occasions, occasion);

        evm::log(OccasionListed {
            id: total_occasions,
            name,
            cost,
            tickets: max_tickets,
        });

        Ok(())
    }

    #[payable]
    pub fn mint(&mut self, id: U256, seat: U256) -> Result<(), Error> {
        if id == U256::ZERO || id > self.total_occasions.get() {
            return Err(Error::InvalidId);
        }

        let occasion = self.occasions.get(id);
        if msg::value() < occasion.cost {
            return Err(Error::InsufficientPayment);
        }

        if seat > occasion.max_tickets {
            return Err(Error::InvalidSeat);
        }

        if !self.seat_taken.getter(id).get(seat).is_zero() {
            return Err(Error::SeatTaken);
        }

        // Update occasion
        let mut updated_occasion = occasion.clone();
        updated_occasion.tickets -= U256::from(1);
        self.occasions.insert(id, updated_occasion);

        // Update mappings
        self.has_bought.setter(id).insert(msg::sender(), true);
        self.seat_taken.setter(id).insert(seat, msg::sender());
        
        let mut seats = self.seats_taken.get(id);
        seats.push(seat);
        self.seats_taken.insert(id, seats);

        // Mint NFT
        let total_supply = self.erc721.total_supply.get() + U256::from(1);
        self.erc721.total_supply.set(total_supply);
        self.erc721.mint(msg::sender())?;

        evm::log(TicketMinted {
            id,
            seat,
            buyer: msg::sender(),
        });

        Ok(())
    }

    pub fn get_occasion(&self, id: U256) -> Result<Occasion, Error> {
        Ok(self.occasions.get(id))
    }

    pub fn get_seats_taken(&self, id: U256) -> Result<Vec<U256>, Error> {
        Ok(self.seats_taken.get(id))
    }

    #[payable]
    pub fn withdraw(&mut self) -> Result<(), Error> {
        if msg::sender() != self.owner.get() {
            return Err(Error::Unauthorized);
        }

        let balance = evm::balance(evm::current_address());
        evm::transfer(self.owner.get(), balance)?;

