            - q_table.get(state_key).get(action_idx).as_i32();
        
        drop(q_table);
        self.q_table
            .setter(sender)
            .setter(state_key)
            .setter(action_idx)
            .set(I32::try_from(q_table.get(state_key).get(action_idx).as_i32() + (alpha as i32 * delta as i32) / 100).unwrap());

        let mut user_history = self.history.setter(sender);
        user_history.setter(0).set(history.get(1));
        user_history.setter(1).set(history.get(2));
        user_history.setter(2).set(history.get(3));
        user_history.setter(3).set(history.get(4));
        user_history.setter(4).set(player_move);
    }

    pub fn get_history(&self, user: Address) -> [U32; HISTORY_SIZE] {
        let history = self.history.get(user);
        [
            history.get(0),
            history.get(1),
            history.get(2),
            history.get(3),
            history.get(4),
        ]
    }

    #[selector(name = "tokenURI")]
    pub fn token_uri(&self, token_id: U256) -> String {
        let owner = self.nft_owners.get(token_id);
        format!(
            "https://api.dicebear.com/9.x/croodles/png?seed={}{}",
            owner, self.balance_of(owner)
        )
    }

    pub fn encode_state(first: u32, second: u32, third: u32, fourth: u32, fifth: u32) -> u32 {
        first * 3u32.pow(0) + second * 3u32.pow(1) + third * 3u32.pow(2) + fourth * 3u32.pow(3) + fifth * 3u32.pow(4)
    }

    pub fn get_q_value(&self, user: Address, state: u32, action: u32) -> I32 {
        self.q_table.get(user).get(state).get(action)
    }
}

impl Contract {
    fn pseudo_random(seed: u32) -> (u32, u32) {
        let a: u32 = 1664525;
        let c: u32 = 1013904223;
        let new_seed = seed.wrapping_mul(a).wrapping_add(c);
        let random = new_seed % 100;
        (random, new_seed)
    }
}
