/// Import items from the SDK. The prelude contains common traits and macros.
use stylus_sdk::{alloy_primitives::U256, prelude::*};

// Define some persistent storage using the Solidity ABI.
// Counter will be the entrypoint.
sol_storage! {
    #[entrypoint]
    pub struct Counter {
        uint256 number;
    }
}

/// Declare that Counter is a contract with the following external methods.
#[public]
impl Counter {
    /// Gets the number from storage.
    pub fn number(&self) -> U256 {
        self.number.get()
    }

    /// Sets a number in storage to a user-specified value.
    pub fn set_number(&mut self, new_number: U256) {
        self.number.set(new_number);
    }

    /// Sets a number in storage to a user-specified value.
    pub fn mul_number(&mut self, new_number: U256) {
        self.number.set(new_number * self.number.get());
    }

    /// Sets a number in storage to a user-specified value.
    pub fn add_number(&mut self, new_number: U256) {
        self.number.set(new_number + self.number.get());
    }

    /// Increments `number` and updates its value in storage.
    pub fn increment(&mut self) {
        let number = self.number.get();
        self.set_number(number + U256::from(1));
    }
}', '{"stderr": "   Compiling stylus-hello-world v0.1.10 (/opt/wizard-backend/projects/c33ad04a-943b-4692-a314-35a1e6717acc/b02eecc1-72db-41e4-9ec6-4b9dc9eb79c4)\nwarning: unstable feature specified for `-Ctarget-feature`: `reference-types`\n  |\n  = note: this feature is not stably supported; its behavior can change in the future\n\nwarning: `stylus-hello-world` (lib) generated 1 warning\n    Finished `release` profile [optimized] target(s) in 1.40s\n", "stdout": "\u001b[0;0m\u001b[90mBuilding project with Cargo.toml version: 0.1.10\u001b[0;0m\n\u001b[0;0m\u001b[90mstripped custom section from user wasm to remove any sensitive data\u001b[0;0m\n\u001b[0;0m\u001b[90mcontract size: \u001b[38;5;48;1m7.0 KB\u001b[0;0m\u001b[0;0m\n\u001b[0;0m\u001b[90mwasm size: \u001b[38;5;48;1m19.2 KB\u001b[0;0m\u001b[0;0m\n\u001b[0;0m\u001b[90mFile used for deployment hash: ./Cargo.lock\u001b[0;0m\n\u001b[0;0m\u001b[90mFile used for deployment hash: ./Cargo.toml\u001b[0;0m\n\u001b[0;0m\u001b[90mFile used for deployment hash: ./examples/counter.rs\u001b[0;0m\n\u001b[0;0m\u001b[90mFile used for deployment hash: ./rust-toolchain.toml\u001b[0;0m\n\u001b[0;0m\u001b[90mFile used for deployment hash: ./src/lib.rs\u001b[0;0m\n\u001b[0;0m\u001b[90mFile used for deployment hash: ./src/main.rs\u001b[0;0m\n\u001b[0;0m\u001b[90mproject metadata hash computed on deployment: \"bb2203c96ed0c624a12125ead96aaafe5b78b85c4af3e70e610026f79296fcd9\"\u001b[0;0m\n\u001b[0;0m\u001b[90mstripped custom section from user wasm to remove any sensitive data\u001b[0;0m\n\u001b[0;0m\u001b[90mcontract size: \u001b[38;5;48;1m7.0 KB\u001b[0;0m\u001b[0;0m\n", "details": {"status": "success", "project_path": "projects/c33ad04a-943b-4692-a314-35a1e6717acc/b02eecc1-72db-41e4-9ec6-4b9dc9eb79c4", "compilation_time": 1934}}', 'success', 0, '[0;0m[90mBuilding project with Cargo.toml version: 0.1.10[0;0m
