	('63100f24-06cc-4ab6-ae1a-f90ee79d680a', '33513df3-5045-4eff-a1bf-b91fcc1d37b5', '9e8dd25d-9a97-4948-87e3-3042f717719f', 'extern crate alloc;

/// Import items from the SDK. The prelude contains common traits and macros.
use stylus_sdk::{alloy_primitives::U256, prelude::*};

// Define some persistent storage using the Solidity ABI.
// Counter will be the entrypoint.
sol_storage! {
    #[entrypoint]
    pub struct Counter {
        uint256 number;
    }
}

/// Declare that Counter is a contract with the following external methods.
#[public]
impl Counter {
    /// Gets the number from storage.
    pub fn number(&self) -> U256 {
        self.number.get()
    }

    /// Sets a number in storage to a user-specified value.
    pub fn set_number(&mut self, new_number: U256) {
        self.number.set(new_number);
    }

    /// Sets a number in storage to a user-specified value.
    pub fn mul_number(&mut self, new_number: U256) {
        self.number.set(new_number * self.number.get());
    }

    /// Sets a number in storage to a user-specified value.
    pub fn add_number(&mut self, new_number: U256) {
        self.number.set(new_number + self.number.get());
    }

    /// Increments `number` and updates its value in storage.
    pub fn increment(&mut self) {
        let number = self.number.get();
        self.set_number(number + U256::from(1));
    }
}', '{"stderr": "   Compiling proc-macro2 v1.0.92\n   Compiling unicode-ident v1.0.14\n   Compiling version_check v0.9.5\n   Compiling crunchy v0.2.2\n   Compiling tiny-keccak v2.0.2\n   Compiling paste v1.0.15\n   Compiling quote v1.0.38\n   Compiling syn v2.0.95\n   Compiling serde v1.0.217\n   Compiling hashbrown v0.15.2\n   Compiling equivalent v1.0.1\n   Compiling indexmap v2.7.0\n   Compiling unicode-xid v0.2.6\n   Compiling cfg-if v1.0.0\n   Compiling cpufeatures v0.2.16\n   Compiling typenum v1.17.0\n   Compiling const-hex v1.14.0\n   Compiling generic-array v0.14.7\n   Compiling ruint-macro v1.2.1\n   Compiling derive_more-impl v1.0.0\n   Compiling syn-solidity v0.8.18\n   Compiling proc-macro-error-attr2 v2.0.0\n   Compiling memchr v2.7.4\n   Compiling heck v0.5.0\n   Compiling dunce v1.0.5\n   Compiling alloy-sol-macro-input v0.8.18\n   Compiling proc-macro-error2 v2.0.1\n   Compiling itoa v1.0.14\n   Compiling syn v1.0.109\n   Compiling alloy-sol-macro-expander v0.8.18\n   Compiling serde_spanned v0.6.8\n   Compiling toml_datetime v0.6.8\n   Compiling proc-macro-error-attr v1.0.4\n   Compiling serde_json v1.0.135\n   Compiling target-triple v0.1.3\n   Compiling winnow v0.6.22\n   Compiling alloy-sol-macro v0.8.18\n   Compiling toml_edit v0.22.22\n   Compiling crypto-common v0.1.6\n   Compiling block-buffer v0.10.4\n   Compiling aho-corasick v1.1.3\n   Compiling derive_more v1.0.0\n   Compiling ruint v1.12.4\n   Compiling proc-macro-error v1.0.4\n   Compiling regex-syntax v0.8.5\n   Compiling hex-literal v0.4.1\n   Compiling ryu v1.0.18\n   Compiling foldhash v0.1.4\n   Compiling bytes v1.9.0\n   Compiling alloy-primitives v0.8.14\n   Compiling regex-automata v0.4.9\n   Compiling digest v0.10.7\n   Compiling toml v0.8.19\n   Compiling serde_derive v1.0.217\n   Compiling keccak v0.1.5\n   Compiling unicode-segmentation v1.12.0\n   Compiling termcolor v1.4.1\n   Compiling glob v0.3.2\n   Compiling trybuild v1.0.101\n   Compiling convert_case v0.6.0\n   Comp