use stylus_sdk::{alloy_primitives::*, prelude::*};

use alloc::{collections::BTreeMap, vec, vec::Vec};

use libbucharesthashing::{immutables::*, prover, prover::Piece};

pub type Board = BTreeMap<u32, (Piece, u32)>;
pub type ThreatMap = BTreeMap<u32, Vec<u32>>;

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

fn xy_to_pos(row_size: u32, x: u32, y: u32) -> u32 {
    y.wrapping_mul(row_size).wrapping_add(x)
}

fn in_bounds(row_size: u32, x: u32, y: u32) -> bool {
    x < row_size && y < row_size
}

struct ThreatTracker {
    threats: ThreatMap,
    row_size: u32,
}

impl ThreatTracker {
    fn new(row_size: u32) -> Self {
        Self {
            threats: BTreeMap::new(),
            row_size,
        }
    }

    fn get_threats(&self, king_pos: u32) -> Option<&Vec<u32>> {
        self.threats.get(&king_pos)
    }
    
    fn calculate_threats(&mut self, board: &Board, king_pos: u32) -> Vec<u32> {
        let (king_x, king_y) = pos_to_xy(self.row_size, king_pos);
        let mut threats = vec![];
        
        macro_rules! piece_add_threat_if_valid {
            ($piece:ident, $x:expr, $y:expr) => {
                if in_bounds(self.row_size, $x, $y) {
                    let pos = xy_to_pos(self.row_size, $x, $y);
                    if let Some((Piece::$piece, n)) = board.get(&pos) {
                        threats.push(*n);
                    }
                }
            };
        }
        
        // Pawn threats
        for dx in [-1, 1] {
            let x = king_x.wrapping_add_signed(dx);
            let y = king_y.wrapping_sub(1);
            piece_add_threat_if_valid!(PAWN, x, y);
        }
        
        // Knight threats
        for (dx, dy) in [
            (-2, -1), (-2, 1), (-1, -2), (-1, 2),
            (1, -2), (1, 2), (2, -1), (2, 1),
        ] {
            piece_add_threat_if_valid!(
                KNIGHT,
                king_x.wrapping_add_signed(dx),
                king_y.wrapping_add_signed(dy)
            );
        }
        
        // Rook/Queen threats
        for (dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
            let mut x = king_x;
            let mut y = king_y;
            loop {
                x = x.wrapping_add_signed(dx);
                y = y.wrapping_add_signed(dy);
                
                if !in_bounds(self.row_size, x, y) {
                    break;
                }
                piece_add_threat_if_valid!(CASTLE, x, y);
                piece_add_threat_if_valid!(QUEEN, x, y);
            }
        }
        
        // Bishop/Queen threats
        for (dx, dy) in [(-1, -1), (-1, 1), (1, -1), (1, 1)] {
            let mut x = king_x;
            let mut y = king_y;
            loop {
                x = x.wrapping_add_signed(dx);
                y = y.wrapping_add_signed(dy);
                if !in_bounds(self.row_size, x, y) {
                    break;
                }
                piece_add_threat_if_valid!(BISHOP, x, y);
                piece_add_threat_if_valid!(QUEEN, x, y);
            }
        }
        
        // King threats
        for dx in [-1, 0, 1] {
            for dy in [-1, 0, 1] {
                let x = king_x.wrapping_add_signed(dx);
                let y = king_y.wrapping_add_signed(dy);
                if dx == 0 && dy == 0 || xy_to_pos(self.row_size, x, y) == king_pos {
                    continue;
                }
                piece_add_threat_if_valid!(KING, x, y);
            }
        }
        
        // Store the calculated threats for this king position
        self.threats.insert(king_pos, threats.clone());
        
        threats
    }
    
    fn update_for_new_piece(&mut self, board: &Board, pos: u32, old_piece: Option<Piece>, new_piece: Piece) {
        // If a king''s position is overwritten, remove it from our threat map
        if let Some(Piece::KING) = old_piece {
            self.threats.remove(&pos);
        }
        
        // For any king in our threat map, check if the new piece placement affects its threats
        let kings_to_recalculate: Vec<u32> = self.threats.keys().cloned().collect();
        
        for king_pos in kings_to_recalculate {
            // Recalculate threats for this king
            self.calculate_threats(board, king_pos);
        }
    }
}

pub fn solve(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    let row_size = BOARD_SIZE.isqrt();
    let mut board = BTreeMap::new();
    let mut last_king = None;
    let mut threat_tracker = ThreatTracker::new(row_size);
    
    for i in start..MAX_TRIES {
        let e = prover::hash(starting_hash, i);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;
        
        // Get the old piece at this position (if any)
        let old_piece = board.get(&pos).map(|(piece, _)| *piece);
        
        // Insert the new piece
        board.insert(pos, (p, i));
        
        // Update our threat tracker
        threat_tracker.update_for_new_piece(&board, pos, old_piece, p);
        
        // If this is a king, update our last king reference
        if p == Piece::KING {
            last_king = Some((pos, i));
        }
        
        // Check if we have enough threats for the last king
        if let Some((last_king_pos, last_king_nonce)) = last_king {
            // Get threats from our tracker, or calculate if needed
            let threats = match threat_tracker.get_threats(last_king_pos) {
                Some(t) => t.clone(),
                None => threat_tracker.calculate_threats(&board, last_king_pos),
            };
            
            if threats.len() >= CHECKS_NEEDED as usize {
                let mut result_threats = threats.clone();
                result_threats.push(last_king_nonce);
                return Some((*result_threats.iter().min().unwrap(), i));
            }
        }
    }
    None
}

#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        Ok(solve(hash.as_slice(), from).unwrap())
    }
}

#[cfg(all(test, not(target_arch = "wasm32")))]
mod test {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #![proptest_config(ProptestConfig { cases: 5000, ..Default::default() })]

        #[test]
        fn test_solve(starting_hash in any::<[u8; 64]>()) {
            let (e_l, e_h) = solve(&starting_hash, 0).unwrap();
            let (t_l, t_h) = solve(&starting_hash, e_l).unwrap();
            assert_eq!((e_l, e_h), (t_l, t_h), "user contract not consistent. {e_l} != {t_l} or {e_h} != {t_h}");
            let (p_l, p_h) = prover::default_solve(&starting_hash, e_l).unwrap();
            assert_eq!(
                (e_l, e_h), (p_l, p_h),
                "user contract inconsistent with reference. {e_l} != {p_l} or {e_h} != {p_h}"
            );
        }
    }
