}

pub fn solve(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    let row_size = BOARD_SIZE.isqrt();
    let mut board = BTreeMap::new();
    let mut last_king = None;
    for i in start..MAX_TRIES {
        let e = prover::hash(starting_hash, i);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;
        board.insert(pos, (p, i));
        if p == Piece::KING {
            last_king = Some((pos, i));
            let mut threats = in_check_threats(&board, row_size, pos);
            if threats.len() >= CHECKS_NEEDED as usize {
                threats.push(i);
                return Some((*threats.iter().min().unwrap(), i));
            }
        } else {
            if let Some((last_king_pos, last_king_nonce)) = last_king {
                let (king_x, king_y) = pos_to_xy(row_size, last_king_pos);
                let (piece_x, piece_y) = pos_to_xy(row_size, pos);

                let mut solved = false;

                if p == Piece::PAWN {
                    if piece_y + 1 == king_y && (piece_x.wrapping_add_signed(1) == king_x || piece_x.wrapping_sub(1) == king_x) {
                        solved = true;
                    }
                }

                if p == Piece::CASTLE || p == Piece::QUEEN {
                    if king_x == piece_x || king_y == piece_y {
                        solved = true;
                    }
                }

                if p == Piece::BISHOP || p == Piece::QUEEN {
                    let dx = if king_x > piece_x { king_x - piece_x } else { piece_x - king_x };
                    let dy = if king_y > piece_y { king_y - piece_y } else { piece_y - king_y };

                    if dx == dy {
                        solved = true;
                    }
                }

                if solved {
                    return Some((last_king_pos, i));
                }
            }
        }
    }
    None
}

