#![no_std]

// Imports nécessaires pour Stylus sur The Wizard
extern crate alloc;
use alloc::vec::Vec;
use stylus_sdk::prelude::*;
use stylus_sdk::msg;
use stylus_sdk::evm::log;
use stylus_sdk::storage::StorageAddress;
use alloy_primitives::{Address, U256};

// Structure du contrat
#[storage]
struct WalletAgentContract {
    owner: StorageAddress,       // Adresse de l''AI Agent ou du wallet qui contrôle
    uniswap_pool: StorageAddress, // Adresse du pool Uniswap v4
}

// Interface Uniswap v4 (simplifiée)
const UNISWAP_V4_POOL_ABI: &[u8] = b"function swap(address,bool,int256,bytes) external returns (int256,int256)";

// Implémentation
#[public]
impl WalletAgentContract {
    // Constructeur
    #[constructor]
    fn new(pool_address: Address) {
        unsafe {
            Self::init(Self {
                owner: StorageAddress::new(msg::sender()),
                uniswap_pool: StorageAddress::new(pool_address),
            });
        }
    }

    // Modifier l''owner
    #[callable]
    fn set_owner(&mut self, new_owner: Address) -> Result<(), Vec<u8>> {
        if msg::sender() != self.owner.get() {
            return Err(b"Only owner can call this".to_vec());
        }
        self.owner.set(new_owner);
        Ok(())
    }

    // Exécuter un swap (achat/vente)
    #[callable]
    fn execute_swap(
        &mut self,
        token_in: Address,
        amount_in: U256,
        zero_for_one: bool,
        min_amount_out: U256,
    ) -> Result<(U256, U256), Vec<u8>> {
        if msg::sender() != self.owner.get() {
            return Err(b"Unauthorized".to_vec());
        }

        let pool = self.uniswap_pool.get();
        let calldata = encode_swap_call(token_in, zero_for_one, amount_in);

        // Appel au pool Uniswap v4
        let (amount0_delta, amount1_delta) = stylus_sdk::call::call(
            pool,
            UNISWAP_V4_POOL_ABI,
            &calldata,
        )?;

        // Vérifie le slippage
        let amount_out = if zero_for_one { amount1_delta } else { amount0_delta };
        if amount_out < min_amount_out {
            return Err(b"Slippage too high".to_vec());
        }

        Ok((amount0_delta, amount1_delta))
    }

    // Hook after_swap
    #[hook(after_swap)]
    fn after_swap_hook(&self, _pool: Address, amount0: U256, amount1: U256) -> Result<(), Vec<u8>> {
        log(&alloc::format!(
            "Swap executed: amount0={}, amount1={}",
            amount0, amount1
        ));
        Ok(())
    }
}

// Helper pour encoder l''appel au swap
fn encode_swap_call(token_in: Address, zero_for_one: bool, amount_in: U256) -> Vec<u8> {
    let mut data = Vec::new();
    data.extend_from_slice(&[0x12, 0x34, 0x56, 0x78]); // Selector fictif
    data.extend_from_slice(&token_in.to_vec());
    data.push(if zero_for_one { 1 } else { 0 });
    data.extend_from_slice(&amount_in.to_be_bytes::<32>());
    data.extend_from_slice(&[0; 32]); // Placeholder pour bytes data
    data
}

// Entrypoint
#[entrypoint]
fn user_main(_vm: &mut stylus_sdk::vm::VM, input: Vec<u8>) -> Result<Vec<u8>, Vec<u8>> {
    stylus_sdk::dispatch(input)
