extern crate alloc;
use alloc::vec::Vec;
use stylus_sdk::prelude::*;
use stylus_sdk::storage::StorageAddress;
use alloy_primitives::{Address, U256};

#[storage]
struct WalletAgentContract {
    owner: StorageAddress,
    uniswap_pool: StorageAddress,
}

#[public]
impl WalletAgentContract {
    fn init(&mut self, pool_address: Address) -> Result<(), Vec<u8>> {
        self.owner.set(self.vm().msg_sender());
        self.uniswap_pool.set(pool_address);
        Ok(())
    }

    fn set_owner(&mut self, new_owner: Address) -> Result<(), Vec<u8>> {
        if self.vm().msg_sender() != self.owner.get() {
            return Err(vec![b''O'', b''n'', b''l'', b''y'', b'' '', b''o'', b''w'', b''n'', b''e'', b''r'']);
        }
        self.owner.set(new_owner);
        Ok(())
    }

    fn execute_swap(
        &mut self,
        token_in: Address,
        amount_in: U256,
        zero_for_one: bool,
        _min_amount_out: U256,
    ) -> Result<Vec<u8>, Vec<u8>> {
        if self.vm().msg_sender() != self.owner.get() {
            return Err(vec![b''U'', b''n'', b''a'', b''u'', b''t'', b''h'', b''o'', b''r'', b''i'', b''z'', b''e'', b''d'']);
        }

        let pool = self.uniswap_pool.get();
        let calldata = encode_swap_call(token_in, zero_for_one, amount_in);

        let result = self.vm().call(self, pool, &calldata)?.return_data;
        Ok(result)
    }
}

fn encode_swap_call(token_in: Address, zero_for_one: bool, amount_in: U256) -> Vec<u8> {
    let mut data = Vec::new();
    data.extend_from_slice(&[0x12, 0x34, 0x56, 0x78]); // Dummy selector
    data.extend_from_slice(&token_in.to_vec());
    data.push(if zero_for_one { 1 } else { 0 });
    data.extend_from_slice(&amount_in.to_be_bytes::<32>());
    data.extend_from_slice(&[0; 32]); // Placeholder
    data
}

#[entrypoint]
fn main(input: Vec<u8>) -> Result<Vec<u8>, Vec<u8>> {
    let mut contract = unsafe { WalletAgentContract::load() };
    stylus_sdk::entrypoint::dispatch(&mut contract, input)
}
