use stylus_sdk::{alloy_primitives::*, prelude::*};

use alloc::{collections::BTreeMap, vec, vec::Vec};

use libbucharesthashing::{immutables::*, prover, prover::Piece};

/* ~~~~~~~~~~~~~~ BOARD IMPLEMENTATION ~~~~~~~~~~~~~~ */

/// Board that this game is played on. Could be of any size. This could
/// be optimised for gas golfing.
pub type Board = BTreeMap<u32, (Piece, u32)>;

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

fn xy_to_pos(row_size: u32, x: u32, y: u32) -> u32 {
    y.wrapping_mul(row_size).wrapping_add(x)
}

fn in_bounds(row_size: u32, x: u32, y: u32) -> bool {
    x < row_size && y < row_size
}

// Custom function to replace the macro
fn piece_add_threat_if_valid(board: &Board, row_size: u32, threats: &mut Vec<u32>, piece: Piece, x: u32, y: u32) {
    if in_bounds(row_size, x, y) {
        if let Some((board_piece, n)) = board.get(&xy_to_pos(row_size, x, y)) {
            if *board_piece == piece {
                threats.push(*n);
            }
        }
    }
}

// Find the in check threats for the king given, returning the nonces of
// the threats.
fn in_check_threats(board: &Board, row_size: u32, king_pos: u32) -> Vec<u32> {
    let (king_x, king_y) = pos_to_xy(row_size, king_pos);
    let mut threats = Vec::new(); // Initializing with exact capacity would be ideal if known
    
    // Check for pawn threats
    for dx in [-1, 1] {
        let x = king_x.wrapping_add_signed(dx);
        let y = king_y.wrapping_sub(1);
        if x < row_size && y < row_size {
            let pos = y.wrapping_mul(row_size).wrapping_add(x);
            if let Some((board_piece, n)) = board.get(&pos) {
                if *board_piece == Piece::PAWN {
                    threats.push(*n);
                }
            }
        }
    }
    
    // Check for knight threats
    for (dx, dy) in [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)] {
        let x = king_x.wrapping_add_signed(dx);
        let y = king_y.wrapping_add_signed(dy);
        if x < row_size && y < row_size {
            let pos = y.wrapping_mul(row_size).wrapping_add(x);
            if let Some((board_piece, n)) = board.get(&pos) {
                if *board_piece == Piece::KNIGHT {
                    threats.push(*n);
                }
            }
        }
    }
    
    // Check for rook/queen threats
    for (dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
        let mut x = king_x;
        let mut y = king_y;
        loop {
            x = x.wrapping_add_signed(dx);
            y = y.wrapping_add_signed(dy);
            if x >= row_size || y >= row_size {
                break;
            }
            let pos = y.wrapping_mul(row_size).wrapping_add(x);
            if let Some((board_piece, n)) = board.get(&pos) {
                if *board_piece == Piece::CASTLE || *board_piece == Piece::QUEEN {
                    threats.push(*n);
                }
                // Break on any piece (blocking line of sight)
                break;
            }
        }
    }
    
    // Check for bishop/queen threats
    for (dx, dy) in [(-1, -1), (-1, 1), (1, -1), (1, 1)] {
        let mut x = king_x;
        let mut y = king_y;
        loop {
            x = x.wrapping_add_signed(dx);
            y = y.wrapping_add_signed(dy);
            if x >= row_size || y >= row_size {
                break;
            }
            let pos = y.wrapping_mul(row_size).wrapping_add(x);
            if let Some((board_piece, n)) = board.get(&pos) {
                if *board_piece == Piece::BISHOP || *board_piece == Piece::QUEEN {
                    threats.push(*n);
                }
                // Break on any piece (blocking line of sight)
                break;
            }
        }
    }
    
    // Check for king threats
    for dx in [-1, 0, 1] {
        for dy in [-1, 0, 1] {
            // Skip checking against itself
            if dx == 0 && dy == 0 {
                continue;
            }
            let x = king_x.wrapping_add_signed(dx);
            let y = king_y.wrapping_add_signed(dy);
            if x < row_size && y < row_size {
                let pos = y.wrapping_mul(row_size).wrapping_add(x);
                // Skip if we''re checking the king''s own position
                if pos == king_pos {
                    continue;
                }
                if let Some((board_piece, n)) = board.get(&pos) {
                    if *board_piece == Piece::KING {
                        threats.push(*n);
                    }
                }
            }
        }
    }
    
    threats
}

