pragma solidity ^0.8.0; // Not needed for Stylus, included for reference

use stylus_sdk::{
    alloy_primitives::{Address, U256},
    prelude::*,
    storage::{StorageAddress, StorageBool, StorageU256, StorageMap},
    msg, block,
};

// Define the contract storage
sol_storage! {
    #[entrypoint]
    struct SubscriptionService {
        Address owner;              // Contract owner
        U256 subscription_fee;      // Monthly fee (in wei)
        U256 subscription_duration; // Duration in seconds (e.g., 30 days)
        StorageMap<Address, Subscriber> subscribers; // Subscriber data
    }

    struct Subscriber {
        StorageBool is_active;      // Subscription status
        StorageU256 last_payment;   // Timestamp of last payment
        StorageU256 balance;        // Subscriber''s deposited funds
    }
}

// Events (Stylus supports emitting events similarly to Solidity)
#[solidity_event]
pub struct Registered {
    subscriber: Address,
}

#[solidity_event]
pub struct PaymentReceived {
    subscriber: Address,
    amount: U256,
}

#[solidity_event]
pub struct SubscriptionExpired {
    subscriber: Address,
}

// Contract implementation
#[external]
impl SubscriptionService {
    // Constructor-like initialization
    pub fn new() -> Self {
        let mut contract = SubscriptionService::default();
        contract.owner.set(msg::sender());
        contract.subscription_fee.set(U256::from(100_000_000_000_000_000)); // 0.1 ETH in wei
        contract.subscription_duration.set(U256::from(30 * 24 * 60 * 60)); // 30 days in seconds
        contract
    }

    // Register or renew subscription
    #[payable]
    pub fn register_or_renew(&mut self) -> Result<(), Vec<u8>> {
        let caller = msg::sender();
        let amount = msg::value();
        require(amount > U256::ZERO, "Must send some ETH");

        let mut subscriber = self.subscribers.get(caller);
        
        if !subscriber.is_active.get() && subscriber.last_payment.get() == U256::ZERO {
            // New subscriber
            subscriber.is_active.set(true);
            subscriber.last_payment.set(U256::from(block::timestamp()));
            subscriber.balance.set(amount);
            self.emit(Registered { subscriber: caller });
        } else {
            // Existing subscriber
            subscriber.balance.set(subscriber.balance.get() + amount);
            self.emit(PaymentReceived { subscriber: caller, amount });
        }

        self.update_subscription_status(caller)?;
        Ok(())
    }

    // Update subscription status
    fn update_subscription_status(&mut self, subscriber_addr: Address) -> Result<(), Vec<u8>> {
        let mut subscriber = self.subscribers.get(subscriber_addr);
        
        if subscriber.is_active.get() {
            let time_elapsed = U256::from(block::timestamp()) - subscriber.last_payment.get();
            let periods_passed = time_elapsed / self.subscription_duration.get();

            if periods_passed > U256::ZERO {
                let total_cost = periods_passed * self.subscription_fee.get();

                if subscriber.balance.get() >= total_cost {
                    subscriber.balance.set(subscriber.balance.get() - total_cost);
                    subscriber.last_payment.set(
                        subscriber.last_payment.get() + (periods_passed * self.subscription_duration.get())
                    );
                } else {
                    subscriber.is_active.set(false);
                    subscriber.balance.set(U256::ZERO);
                    self.emit(SubscriptionExpired { subscriber: subscriber_addr });
                }
            }
        }
        Ok(())
    }

    // Deposit additional funds
    #[payable]
    pub fn deposit_funds(&mut self) -> Result<(), Vec<u8>> {
        let amount = msg::value();
        require(amount > U256::ZERO, "Must send some ETH");
        let caller = msg::sender();
        let mut subscriber = self.subscribers.get(caller);
        subscriber.balance.set(subscriber.balance.get() + amount);
        self.emit(PaymentReceived { subscriber: caller, amount });
        Ok(())
    }

    // Withdraw funds (owner only)
    pub fn withdraw(&mut self) -> Result<(), Vec<u8>> {
        require(msg::sender() == self.owner.get(), "Only owner can withdraw");
        let balance = msg::balance();
        require(balance > U256::ZERO, "No funds to withdraw");
        msg::transfer(self.owner.get(), balance)?;
        Ok(())
    }

    // Get subscriber info (view function)
    pub fn get_subscriber_info(&self, subscriber: Address) -> (bool, U256, U256) {
        let sub = self.subscribers.get(subscriber);
        (sub.is_active.get(), sub.last_payment.get(), sub.balance.get())
    }

    // Set subscription fee (owner only)
    pub fn set_subscription_fee(&mut self, new_fee: U256) -> Result<(), Vec<u8>> {
        require(msg::sender() == self.owner.get(), "Only owner can set fee");
        self.subscription_fee.set(new_fee);
        Ok(())
    }
}

// Helper macro for require statements
macro_rules! require {
    ($cond:expr, $msg:expr) => {
        if !$cond {
            return Err($msg.as_bytes().to_vec());
        }
    };
}
