        if !subscriber.is_active.get() && subscriber.last_payment.get() == U256::ZERO {
            // New subscriber
            subscriber.is_active.set(true);
            subscriber.last_payment.set(U256::from(self.vm().timestamp()));
            subscriber.balance.set(amount);
            self.log(Registered { subscriber: caller });
        } else {
            // Existing subscriber
            subscriber.balance.set(subscriber.balance.get() + amount);
            self.log(PaymentReceived { subscriber: caller, amount });
        }

        self.update_subscription_status(caller)?;
        Ok(())
    }

    // Update subscription status
    fn update_subscription_status(&mut self, subscriber_addr: StorageAddress) -> Result<(), Vec<u8>> {
        let mut subscriber = self.subscribers.get(subscriber_addr);

        if subscriber.is_active.get() {
            let time_elapsed = U256::from(self.vm().timestamp()) - subscriber.last_payment.get();
            let periods_passed = time_elapsed / self.subscription_duration.get();

            if periods_passed > U256::ZERO {
                let total_cost = periods_passed * self.subscription_fee.get();

                if subscriber.balance.get() >= total_cost {
                    subscriber.balance.set(subscriber.balance.get() - total_cost);
                    subscriber.last_payment.set(
                        subscriber.last_payment.get() + (periods_passed * self.subscription_duration.get())
                    );
                } else {
                    subscriber.is_active.set(false);
                    subscriber.balance.set(U256::ZERO);
                    self.log(SubscriptionExpired { subscriber: subscriber_addr });
                }
            }
        }
        Ok(())
    }

    // Deposit additional funds
    #[payable]
    pub fn deposit_funds(&mut self) -> Result<(), Vec<u8>> {
        let amount = self.vm().value();
        if amount == U256::ZERO {
            return Err("Must send some ETH".into());
        }
        let caller = self.vm().sender();
        let mut subscriber = self.subscribers.get(caller);
        subscriber.balance.set(subscriber.balance.get() + amount);
        self.log(PaymentReceived { subscriber: caller, amount });
        Ok(())
    }

    // Withdraw funds (owner only)
    pub fn withdraw(&mut self) -> Result<(), Vec<u8>> {
        if self.vm().sender() != self.owner.get() {
            return Err("Only owner can withdraw".into());
        }
        let balance = self.vm().balance();
        if balance == U256::ZERO {
            return Err("No funds to withdraw".into());
        }
        self.vm().transfer(self.owner.get(), balance)?;
        Ok(())
    }

    // Get subscriber info (view function)
    pub fn get_subscriber_info(&self, subscriber: StorageAddress) -> Result<(bool, U256, U256), Vec<u8>> {
        let sub = self.subscribers.get(subscriber);
        Ok((sub.is_active.get(), sub.last_payment.get(), sub.balance.get()))
    }

    // Set subscription fee (owner only)
    pub fn set_subscription_fee(&mut self, new_fee: U256) -> Result<(), Vec<u8>> {
        if self.vm().sender() != self.owner.get() {
            return Err("Only owner can set fee".into());
        }
        self.subscription_fee.set(new_fee);
        Ok(())
    }
}
