#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    // Optimized prove function
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        let row_size = BOARD_SIZE.isqrt();
        // Pre-allocate with capacity to avoid reallocations
        let mut board = Vec::with_capacity(32);
        let mut last_king = None;
        
        for i in from..MAX_TRIES {
            let e = prover::hash(hash.as_slice(), i);
            
            // Optimize piece calculation
            let king_id: u8 = Piece::KING.into();
            let p_id: u8 = (e % (king_id as u64 + 1)) as u8;
            let p = unsafe { Piece::try_from_unchecked(p_id) };
            
            let pos: u32 = ((e >> 32) as u32) % BOARD_SIZE;
            
            // Add piece to board
            board.push((pos, p, i));
            
            if p == Piece::KING {
                last_king = Some((pos, i));
                
                // Only check threats when we have a king
                if let Some((king_pos, king_nonce)) = last_king {
                    let threats = in_check_threats(&board, row_size, king_pos);
                    
                    // Check if we have enough threats
                    if threats.len() >= CHECKS_NEEDED as usize {
                        // Find minimum nonce
                        let mut min_nonce = king_nonce;
                        for &threat_nonce in &threats {
                            if threat_nonce < min_nonce {
                                min_nonce = threat_nonce;
                            }
                        }
                        
                        return Ok((min_nonce, i));
                    }
                }
            }
        }
        
        // Bare minimum error message to save gas
        Err(vec![0])
    }
}

