/* ~~~~~~~~~~~~~~ BOARD IMPLEMENTATION ~~~~~~~~~~~~~~ */

/// Using a more gas-efficient representation for the board
/// Fixed-size capacity for small boards is more gas efficient
type Board = Vec<(u32, Piece, u32)>;

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

// Find the in check threats for the king given, returning the nonces of
// the threats.
fn in_check_threats(board: &Board, row_size: u32, king_pos: u32) -> Vec<u32> {
    let (king_x, king_y) = pos_to_xy(row_size, king_pos);
    // Pre-allocate with estimated capacity to avoid reallocations
    let mut threats = Vec::with_capacity(8);
    
    // Use direct board iteration instead of lookups
    for &(pos, piece, nonce) in board {
        // Skip the king itself
        if pos == king_pos {
            continue;
        }
        
        let (piece_x, piece_y) = pos_to_xy(row_size, pos);
        
        match piece {
            // Pawn threats
            Piece::PAWN => {
                // Pawn diagonal attacks
                if piece_y == king_y.wrapping_sub(1) && 
                   (piece_x == king_x.wrapping_add(1) || piece_x == king_x.wrapping_sub(1)) {
                    threats.push(nonce);
                }
            },
            
            // Knight threats
            Piece::KNIGHT => {
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                // Knight moves in L-shape (2,1) or (1,2)
                if (dx == 1 && dy == 2) || (dx == 2 && dy == 1) {
                    threats.push(nonce);
                }
            },
            
            // Rook threats - same row or column
            Piece::CASTLE => {
                if (piece_x == king_x || piece_y == king_y) && is_clear_path(board, piece_x, piece_y, king_x, king_y) {
                    threats.push(nonce);
                }
            },
            
            // Bishop threats - diagonal
            Piece::BISHOP => {
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                if dx == dy && is_clear_path(board, piece_x, piece_y, king_x, king_y) {
                    threats.push(nonce);
                }
            },
            
            // Queen threats - rook + bishop moves
            Piece::QUEEN => {
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                // Same row/column OR diagonal AND clear path
                if ((piece_x == king_x || piece_y == king_y) || dx == dy) && 
                   is_clear_path(board, piece_x, piece_y, king_x, king_y) {
                    threats.push(nonce);
                }
            },
            
            // King threats - adjacent squares
            Piece::KING => {
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                // Kings can only threaten adjacent squares
                if dx <= 1 && dy <= 1 {
                    threats.push(nonce);
                }
            },
        }
    }
    
    threats
}

// Check if there are no pieces between source and destination
fn is_clear_path(board: &Board, src_x: u32, src_y: u32, dst_x: u32, dst_y: u32) -> bool {
    // Same position
    if src_x == dst_x && src_y == dst_y {
        return true;
    }
    
    let dx = if src_x < dst_x { 1 } else if src_x > dst_x { -1 } else { 0 };
    let dy = if src_y < dst_y { 1 } else if src_y > dst_y { -1 } else { 0 };
    
    let mut x = src_x;
    let mut y = src_y;
    
    loop {
        // Move one step
        x = x.wrapping_add_signed(dx);
        y = y.wrapping_add_signed(dy);
        
        // Reached destination?
        if x == dst_x && y == dst_y {
            return true;
        }
        
        // Check if position is occupied
        let pos = y * BOARD_SIZE.isqrt() + x;
        for &(p, _, _) in board {
            if p == pos && !(p == src_x + src_y * BOARD_SIZE.isqrt() || p == dst_x + dst_y * BOARD_SIZE.isqrt()) {
                return false;
            }
        }
    }
}

/* ~~~~~~~~~~~~~~ CONTRACT ENTRYPOINT ~~~~~~~~~~~~~~ */

#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    // Optimized prove function
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        let row_size = BOARD_SIZE.isqrt();
        // Pre-allocate with capacity to avoid reallocations
        let mut board = Vec::with_capacity(32);
        let mut last_king = None;
        
        for i in from..MAX_TRIES {
            let e = prover::hash(hash.as_slice(), i);
            
            // Optimize piece calculation
            let king_id: u8 = Piece::KING.into();
            let p_id: u8 = (e % (king_id as u64 + 1)) as u8;
            let p = unsafe { Piece::try_from_unchecked(p_id) };
            
            let pos: u32 = ((e >> 32) as u32) % BOARD_SIZE;
            
            // Add piece to board
            board.push((pos, p, i));
            
            if p == Piece::KING {
                last_king = Some((pos, i));
                
                // Only check threats when we have a king
                if let Some((king_pos, king_nonce)) = last_king {
                    let threats = in_check_threats(&board, row_size, king_pos);
                    
                    // Check if we have enough threats
                    if threats.len() >= CHECKS_NEEDED as usize {
                        // Find minimum nonce
                        let mut min_nonce = king_nonce;
                        for &threat_nonce in &threats {
                            if threat_nonce < min_nonce {
                                min_nonce = threat_nonce;
                            }
                        }
                        
                        return Ok((min_nonce, i));
                    }
                }
            }
        }
        
        // Bare minimum error message to save gas
        Err(vec![0])
    }
}

