        let y = king_y.wrapping_sub(1);
        if in_bounds(row_size, x, y) {
            let pos = xy_to_pos(row_size, x, y);
            if let Some((Piece::PAWN, n)) = board.get(&pos) {
                threats.push(*n);
            }
        }
    }
    // Knight
    for (dx, dy) in [
        (-2, -1),
        (-2, 1),
        (-1, -2),
        (-1, 2),
        (1, -2),
        (1, 2),
        (2, -1),
        (2, 1),
    ] {
        let x = king_x.wrapping_add_signed(dx);
        let y = king_y.wrapping_add_signed(dy);
        if in_bounds(row_size, x, y) {
            let pos = xy_to_pos(row_size, x, y);
            if let Some((Piece::KNIGHT, n)) = board.get(&pos) {
                threats.push(*n);
            }
        }
    }

    // Rook/Queen
    for (dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
        let mut x = king_x;
        let mut y = king_y;
        loop {
            x = x.wrapping_add_signed(dx);
            y = y.wrapping_add_signed(dy);
            if !in_bounds(row_size, x, y) {
                break;
            }
            let pos = xy_to_pos(row_size, x, y);
            if let Some((piece, n)) = board.get(&pos) {
                if *piece == Piece::CASTLE || *piece == Piece::QUEEN {
                    threats.push(*n);
                }
            }
        }
    }

    // Bishop/Queen
    for (dx, dy) in [(-1, -1), (-1, 1), (1, -1), (1, 1)] {
        let mut x = king_x;
        let mut y = king_y;
        loop {
            x = x.wrapping_add_signed(dx);
            y = y.wrapping_add_signed(dy);
            if !in_bounds(row_size, x, y) {
                break;
            }
            let pos = xy_to_pos(row_size, x, y);
            if let Some((piece, n)) = board.get(&pos) {
                if *piece == Piece::BISHOP || *piece == Piece::QUEEN {
                    threats.push(*n);
                }
            }
        }
    }
    // King
    for dx in [-1, 0, 1] {
        for dy in [-1, 0, 1] {
            if dx == 0 && dy == 0 {
                continue;
            }
            let x = king_x.wrapping_add_signed(dx);
            let y = king_y.wrapping_add_signed(dy);
            if in_bounds(row_size, x, y) {
                let pos = xy_to_pos(row_size, x, y);
                if let Some((Piece::KING, n)) = board.get(&pos) {
                    threats.push(*n);
                }
            }
        }
    }
