use stylus_sdk::{alloy_primitives::*, prelude::*};

use alloc::vec;
use alloc::vec::Vec;

use libbucharesthashing::{immutables::*, prover, prover::Piece};

use std::collections::HashMap;

pub type Board = HashMap<u32, (Piece, u32)>;

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

fn xy_to_pos(row_size: u32, x: u32, y: u32) -> u32 {
    y.wrapping_mul(row_size).wrapping_add(x)
}

fn in_bounds(row_size: u32, x: u32, y: u32) -> bool {
    x < row_size && y < row_size
}

fn calculate_threats(board: &Board, row_size: u32, king_pos: u32) -> (usize, Option<u32>) {
    let (king_x, king_y) = pos_to_xy(row_size, king_pos);
    let mut threat_count = 0;
    let mut min_threat_nonce: Option<u32> = None;
    let mut process_threat = |nonce: u32| {
        threat_count += 1;
        min_threat_nonce = Some(min_threat_nonce.map_or(nonce, |min_n| min_n.min(nonce)));
    };

    for dx in [-1, 1] {
        let x = king_x.wrapping_add_signed(dx);
        let y = king_y.wrapping_sub(1);
        if in_bounds(row_size, x, y) {
            if let Some((Piece::PAWN, n_ref)) = board.get(&xy_to_pos(row_size, x, y)) {
                process_threat(*n_ref);
            }
        }
    }

    for (dx, dy) in [(-2, -1),(-2, 1),(-1, -2),(-1, 2),(1, -2),(1, 2),(2, -1),(2, 1)] {
        let x = king_x.wrapping_add_signed(dx);
        let y = king_y.wrapping_add_signed(dy);
        if in_bounds(row_size, x, y) {
             if let Some((Piece::KNIGHT, n_ref)) = board.get(&xy_to_pos(row_size, x, y)) {
                process_threat(*n_ref);
            }
        }
    }

     for dx in [-1, 0, 1] {
        for dy in [-1, 0, 1] {
            if dx == 0 && dy == 0 { continue; }
            let x = king_x.wrapping_add_signed(dx);
            let y = king_y.wrapping_add_signed(dy);
            if in_bounds(row_size, x, y) {
                if let Some((Piece::KING, n_ref)) = board.get(&xy_to_pos(row_size, x, y)) {
                     process_threat(*n_ref);
                }
            }
        }
    }

    for (step_x, step_y) in [(0, 1), (0, -1), (1, 0), (-1, 0)] {
        let mut current_x = king_x;
        let mut current_y = king_y;
        loop {
            current_x = current_x.wrapping_add_signed(step_x);
            current_y = current_y.wrapping_add_signed(step_y);
            if !in_bounds(row_size, current_x, current_y) { break; }
            let pos = xy_to_pos(row_size, current_x, current_y);
            if let Some((piece, n_ref)) = board.get(&pos) {
                 if *piece == Piece::CASTLE || *piece == Piece::QUEEN {
                    process_threat(*n_ref);
                 }
            }
        }
    }

     for (step_x, step_y) in [(1, 1), (1, -1), (-1, 1), (-1, -1)] {
        let mut current_x = king_x;
        let mut current_y = king_y;
        loop {
            current_x = current_x.wrapping_add_signed(step_x);
            current_y = current_y.wrapping_add_signed(step_y);
            if !in_bounds(row_size, current_x, current_y) { break; }
            let pos = xy_to_pos(row_size, current_x, current_y);
            if let Some((piece, n_ref)) = board.get(&pos) {
                 if *piece == Piece::BISHOP || *piece == Piece::QUEEN {
                    process_threat(*n_ref);
                 }
            }
        }
    }
    (threat_count, min_threat_nonce)
}

pub fn solve(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    let row_size = BOARD_SIZE.isqrt();
    let mut board: Board = HashMap::new();
    let mut last_king: Option<(u32, u32)> = None;
    let min_pieces_needed = CHECKS_NEEDED as usize + 1;

    for i in start..MAX_TRIES {
        let e = prover::hash(starting_hash, i);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;
        
        board.insert(pos, (p, i));

        if p == Piece::KING {
            last_king = Some((pos, i));
        }

        if let Some((last_king_pos, last_king_nonce)) = last_king {
            if board.len() >= min_pieces_needed {
                let (threat_count, min_threat_nonce_opt) = calculate_threats(&board, row_size, last_king_pos);
                if threat_count >= CHECKS_NEEDED as usize {
                    let final_min_nonce = match min_threat_nonce_opt {
                        Some(min_threat_nonce) => last_king_nonce.min(min_threat_nonce),
                        None => last_king_nonce,
                    };
                    return Some((final_min_nonce, i));
                }
            }
        }
    }
    None
}

#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        match solve(hash.as_slice(), from) {
             Some(result) => Ok(result),
             None => Err(vec![])
        }
    }
}

