use libbucharesthashing::{immutables::*, prover, prover::Piece};

pub type Board = Vec<(u32, Piece, u32)>;

#[cfg(test)]
#[derive(Debug, Clone)]
struct TraceEntry {
    iteration: u32,
    piece: Piece,
    pos: u32,
    replaced_piece_details: Option<(u32, Piece)>,
    threats_before_update: Vec<u32>,
    threats_after_update: Vec<u32>,
    is_king_placement: bool,
    end_condition_check_happened: bool,
    king_nonce_added_to_threats: bool,
    final_threats_at_return: Option<Vec<u32>>,
}

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

fn calculate_threats_from_state(
    square_state: &Vec<Option<(u32, Piece)>>,
    row_size: u32,
    king_pos: u32,
) -> Vec<u32> {
    let mut threats = vec![];
    for piece_pos_usize in 0..square_state.len() {
        if let Some((nonce, piece)) = square_state[piece_pos_usize] {
            let piece_pos = piece_pos_usize as u32;
            if is_checking(row_size, king_pos, piece_pos, piece) {
                threats.push(nonce);
            }
        }
    }
    threats
}


fn is_checking(row_size: u32, king_pos: u32, piece_pos: u32, piece: Piece) -> bool {
    let (king_x, king_y) = pos_to_xy(row_size, king_pos);
    let (piece_x, piece_y) = pos_to_xy(row_size, piece_pos);

    let dx = if king_x > piece_x {
        king_x - piece_x
    } else {
        piece_x - king_x
    };
    let dy = if king_y > piece_y {
        king_y - piece_y
    } else {
        piece_y - king_y
    };

    if dx == 0 && dy == 0 {
        return false;
    }

    match piece {
        Piece::PAWN => piece_y + 1 == king_y && dx == 1,
        Piece::CASTLE => dx == 0 || dy == 0,
        Piece::QUEEN => dx == 0 || dy == 0 || dx == dy,
        Piece::BISHOP => dx == dy,
        Piece::KNIGHT => dx * dy == 2,
        Piece::KING => dx <= 1 && dy <= 1,
    }
}

#[cfg(not(test))]
pub fn solve(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    solve_impl(starting_hash, start)
}

#[cfg(test)]
pub fn solve(
    starting_hash: &[u8],
    start: u32,
    record_trace: bool,
) -> (Option<(u32, u32)>, Vec<TraceEntry>) {
    solve_impl(starting_hash, start, record_trace)
}

#[cfg(not(test))]
fn solve_impl(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    let row_size = BOARD_SIZE.isqrt();
    let mut square_state: Vec<Option<(u32, Piece)>> = vec![None; BOARD_SIZE as usize];
    let mut last_king: Option<(u32, u32)> = None;

    let mut pre_sim_threats: Vec<u32> = vec![];
    for j in 0..start {
        let e = prover::hash(starting_hash, j);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;

        let replaced_details = square_state[pos as usize].clone(); 
        match replaced_details {
            Some((existing_nonce, existing_piece)) => {
                if let Some((last_king_pos, _)) = last_king {
                    if is_checking(row_size, last_king_pos, pos, existing_piece) {
                        if let Some(index) = pre_sim_threats.iter().position(|&nonce| nonce == existing_nonce) {
                            pre_sim_threats.swap_remove(index);
                        }
                    }
                }
            }
            None => {} 
        }
        square_state[pos as usize] = Some((j, p));
        if p == Piece::KING {
            last_king = Some((pos, j));
            pre_sim_threats = calculate_threats_from_state(&square_state, row_size, pos);
        } else if let Some((last_king_pos, _)) = last_king {
            if is_checking(row_size, last_king_pos, pos, p) {
                pre_sim_threats.push(j);
            }
        }
    }

    for i in start..MAX_TRIES {
        let e = prover::hash(starting_hash, i);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;

        square_state[pos as usize] = Some((i, p));
        
        if p == Piece::KING {
            last_king = Some((pos, i));
        }

        if let Some((last_king_pos, last_king_nonce)) = last_king { 
            
            let current_threats = calculate_threats_from_state(&square_state, row_size, last_king_pos);

            if current_threats.len() >= CHECKS_NEEDED as usize {
                let mut threats_with_king = current_threats.clone();
                threats_with_king.push(last_king_nonce);
                
                let min_nonce_found = threats_with_king.iter().min().unwrap(); 
                
                return Some((*min_nonce_found, i));
             }
         } 

    }

    None
}

#[cfg(test)]
fn solve_impl(
    starting_hash: &[u8],
    start: u32,
    record_trace: bool, 
) -> (Option<(u32, u32)>, Vec<TraceEntry>) {
    let row_size = BOARD_SIZE.isqrt();
    let mut square_state: Vec<Option<(u32, Piece)>> = vec![None; BOARD_SIZE as usize];
    let mut last_king: Option<(u32, u32)> = None;
    let mut trace: Vec<TraceEntry> = Vec::new();

    let mut pre_sim_threats: Vec<u32> = vec![];
    for j in 0..start {
        let e = prover::hash(starting_hash, j);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;
        let replaced_details = square_state[pos as usize].clone(); 
        match replaced_details {
            Some((existing_nonce, existing_piece)) => {
                if let Some((last_king_pos, _)) = last_king {
                    if is_checking(row_size, last_king_pos, pos, existing_piece) {
                        if let Some(index) = pre_sim_threats.iter().position(|&nonce| nonce == existing_nonce) {
                            pre_sim_threats.swap_remove(index);
                        }
                    }
                }
            }
            None => {} 
        }
        square_state[pos as usize] = Some((j, p));
        if p == Piece::KING {
            last_king = Some((pos, j));
            pre_sim_threats = calculate_threats_from_state(&square_state, row_size, pos);
        } else if let Some((last_king_pos, _)) = last_king {
            if is_checking(row_size, last_king_pos, pos, p) {
                pre_sim_threats.push(j);
            }
        }
    }

    for i in start..MAX_TRIES {
        let e = prover::hash(starting_hash, i);
        let king_id: u8 = Piece::KING.into();
        let p_id: u8 = (e % (king_id as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;

        let replaced_details_for_log = square_state[pos as usize].clone();

        let mut current_entry = if record_trace {
             Some(TraceEntry {
                iteration: i,
                piece: p,
                pos,
                replaced_piece_details: replaced_details_for_log,
                threats_before_update: vec![],
                threats_after_update: vec![],
                is_king_placement: false, 
                end_condition_check_happened: false, 
                king_nonce_added_to_threats: false, 
                final_threats_at_return: None, 
             })
        } else { None };

        square_state[pos as usize] = Some((i, p)); 

        let mut king_placement_this_iter = false;
        if p == Piece::KING {
            king_placement_this_iter = true;
            last_king = Some((pos, i));
        }
        if let Some(ref mut entry) = current_entry { entry.is_king_placement = king_placement_this_iter; }

        let mut returned_this_iter = false;
        if let Some((last_king_pos, last_king_nonce)) = last_king { 
            
            let current_threats = calculate_threats_from_state(&square_state, row_size, last_king_pos);

            if let Some(ref mut entry) = current_entry {
                entry.threats_before_update = current_threats.clone(); 
                entry.threats_after_update = current_threats.clone(); 
            }
            
            if current_threats.len() >= CHECKS_NEEDED as usize {
                 let mut threats_with_king = current_threats.clone(); 
                 threats_with_king.push(last_king_nonce);

                 if let Some(min_nonce_found) = threats_with_king.iter().min() {
                     let result = Some((*min_nonce_found, i)); 
                     returned_this_iter = true;

                     if let Some(ref mut entry) = current_entry {
                         entry.end_condition_check_happened = true;
                         entry.final_threats_at_return = Some(current_threats); 
                         if record_trace { trace.push(entry.clone()); } 
                     }
                     return (result, trace); 
                 }
             }
         } else {
            if let Some(ref mut entry) = current_entry {
                 entry.threats_before_update = vec![]; 
                 entry.threats_after_update = vec![]; 
            }
         }

        if !returned_this_iter {
             if let Some(entry) = current_entry {
                 if record_trace { trace.push(entry); }
             }
        }
    }

    (None, trace)
}

#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        #[cfg(not(test))]
        let result = solve(hash.as_slice(), from);

        #[cfg(test)]
        let (result, _) = solve(hash.as_slice(), from, false);

        match result {
             Some(r) => Ok(r),
             None => Err(vec![])
        }
    }
}

#[cfg(all(test, not(target_arch = "wasm32")))]
mod test {
    use super::*;
    use proptest::prelude::*;
    use libbucharesthashing::prover;
    use std::fs;
    use std::path::PathBuf;
    use std::fmt::Write;
    use super::TraceEntry;

    fn format_trace_to_markdown(
        hash: &[u8; 32],
        start_nonce: u32,
        result: Option<(u32, u32)>,
        trace: &Vec<TraceEntry>,
    ) -> String {
        let mut md = String::new();
        writeln!(md, "# Solve Trace").unwrap();
        writeln!(md, "- **Hash:** `{:?}`", hash).unwrap();
        writeln!(md, "- **Start Nonce:** `{}`", start_nonce).unwrap();
        writeln!(md, "- **Result:** `{:?}`", result).unwrap();
        writeln!(md).unwrap();
        writeln!(md, "## Trace Table").unwrap();
        writeln!(md, "| Iteration | Piece | Pos | Replaced Nonce | Replaced Piece | Threats Before | Threats After | King Placed | End Check | King Nonce Added | Final Threats |").unwrap();
        writeln!(md, "|---|---|---|---|---|---|---|---|---|---|---|").unwrap();

        for entry in trace {
            let replaced_n = entry.replaced_piece_details.map_or_else(|| "N/A".to_string(), |(n, _)| n.to_string());
            let replaced_p = entry.replaced_piece_details.map_or_else(|| "N/A".to_string(), |(_, p)| format!("{:?}", p));
            let final_threats_str = entry.final_threats_at_return.as_ref().map_or_else(|| "N/A".to_string(), |v| format!("{:?}", v));

             writeln!(md, "| {} | {:?} | {} | {} | {} | {:?} | {:?} | {} | {} | {} | {} |",
                 entry.iteration,
                 entry.piece,
                 entry.pos,
                 replaced_n,
                 replaced_p,
                 entry.threats_before_update,
                 entry.threats_after_update,
                 entry.is_king_placement,
                 entry.end_condition_check_happened,
                 entry.king_nonce_added_to_threats,
                 final_threats_str
             ).unwrap();
        }
        md
    }

    fn write_log_file(log_content: &str, failure_desc: &str) {
        let log_dir = PathBuf::from("target/proptest-logs");
        fs::create_dir_all(&log_dir).expect("Failed to create log directory");
        let log_file_path = log_dir.join(format!("failure_{}.md", failure_desc));
        fs::write(&log_file_path, log_content)
            .expect(&format!("Failed to write log file: {:?}", log_file_path));
        println!("Wrote detailed failure log to: {:?}", log_file_path);
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 5000, ..Default::default() })]
        #[test]
        fn test_solve(starting_hash: [u8; 32]) {

            println!("\n>>>>>>>>>> Testing Hash: {:?} <<<<<<<<<<", starting_hash);

            // Run user solve from start 0
            let (solve_result_0, trace_0) = solve(&starting_hash, 0, true);
            println!("User solve(0) found: {:?}", solve_result_0);

            // Run prover solve from start 0
            println!("\n--- Comparing with prover::default_solve starting from 0 ---");
            let prover_result_0 = prover::default_solve(&starting_hash, 0);
             println!("prover::default_solve(0) found: {:?}", prover_result_0);

            // Compare the results from start 0
            if prover_result_0 != solve_result_0 {
                let failure_desc = format!("prover_mismatch_start_0_hash_{:02x}{:02x}", starting_hash[0], starting_hash[1]);
                 let log_content = format!(
                     "## Prover Mismatch Failure (start=0)\n\nUser solve found `{:?}` but prover found `{:?}` when starting from nonce `0`.\n\n{}",
                     solve_result_0,
                     prover_result_0,
                     format_trace_to_markdown(&starting_hash, 0, solve_result_0, &trace_0)
                 );
                 write_log_file(&log_content, &failure_desc);
                 // Panic showing prover expected vs user actual
                 panic!("User contract inconsistent with reference from start=0. Expected {:?}, got {:?}", 
                        prover_result_0, solve_result_0); 
            } else {
                // Results match, test passes for this part.
                println!("User solve(0) matches prover::default_solve(0). OK.");
            }

             println!("\n<<<<<<<<<< Test PASSED for Hash: {:?} >>>>>>>>>>", starting_hash);
