        self.disputeDefender.insert(dispute_id, defender);
        self.disputeStatus.insert(dispute_id, U256::from(1)); // InProgress
        self.disputeTimestamp.insert(dispute_id, U256::from(self.vm().block_timestamp()));

        // Emit event through VM
        self.emit_dispute_initiated(dispute_id, caller, defender);

        Ok(dispute_id)
    }

    /// Resolves a dispute
    pub fn resolve_dispute(&mut self, dispute_id: FixedBytes<32>) -> Result<(), Vec<u8>> {
        // Check dispute exists
        if !self.dispute_exists(dispute_id) {
            return Err("Dispute not found".into());
        }
        
        // Check dispute is in progress
        let status = self.disputeStatus.get(dispute_id);
        if status != U256::from(1) {
            return Err("Dispute not in progress".into());
        }
        
        // Check challenge period has passed
        let timestamp = self.disputeTimestamp.get(dispute_id);
        if self.vm().block_timestamp() <= timestamp.as_limbs()[0] + 86400 {
            return Err("Dispute is still in challenge period".into());
        }

        // Resolve the dispute
        self.disputeStatus.insert(dispute_id, U256::from(2)); // Resolved
        
        // Emit event
        self.emit_dispute_resolved(dispute_id);
        
        Ok(())
    }
    
    /// Checks if a dispute exists
    pub fn dispute_exists(&self, dispute_id: FixedBytes<32>) -> bool {
        self.disputeChallenger.get(dispute_id) != Address::ZERO
    }

    /// Benchmark Black-Scholes option pricing algorithm
    pub fn benchmark_black_scholes(&mut self) -> U256 {
        // Initial values for the Black-Scholes model
        let s = 100.0f32; // Current price
        let k = 100.0f32; // Strike price
        let r = 0.05f32;  // Risk-free rate
        let sigma = 0.2f32; // Volatility
        let t = 1.0f32;   // Time to expiration in years
        
        // Run 50 iterations to simulate computational load
        let mut d1 = 0.0f32;
        
        for _ in 0..50 {
            // Calculate d1
            let numerator = (s/k).ln() + (r + 0.5 * sigma * sigma) * t;
            let denominator = sigma * t.sqrt();
            d1 = numerator / denominator;
            
            // Calculate d2
            let d2 = d1 - sigma * t.sqrt();
            
            // Normal distribution approximation (simplified)
            let nd1 = 0.5 * (1.0 + (d1 / (2.0f32.sqrt())).tanh());
            let nd2 = 0.5 * (1.0 + (d2 / (2.0f32.sqrt())).tanh());
            
            // Calculate call price
            let call = s * nd1 - k * (-r * t).exp() * nd2;
            
            // Use the result to prevent optimizer from removing the calculation
            if call > 0.0 {
                d1 = d1 + 0.000001;
            }
        }
        
        // Convert the result to U256
        let result = (d1 * 1000.0) as u64;
        U256::from(result)
    }

    /// Hook for Uniswap v4-style swaps
    pub fn hook_before_swap(
        &mut self,
        pool_id: FixedBytes<32>,
        sender: Address,
        amount_in: U256,
        token_in: Address
    ) -> Result<U256, Vec<u8>> {
        // Basic validation
        if amount_in == U256::ZERO {
            return Err("Invalid swap amount".into());
        }
        
        // Calculate a dynamic fee (simplified)
        let fee = U256::from(3) * amount_in / U256::from(1000);
        
        // Record the swap in our number storage
        self.number.set(amount_in);
        self.benchmarkData.insert(pool_id, amount_in);
        
        Ok(fee)
    }
}

/// Helper methods implementation (non-public)
impl Counter {
    /// Generates a dispute ID from a transaction hash and challenger address
    fn generate_dispute_id(&self, tx_hash: FixedBytes<32>, caller: Address) -> FixedBytes<32> {
        // Simple deterministic ID generation (XOR of tx_hash and caller with timestamp)
        let timestamp_bytes = U256::from(self.vm().block_timestamp()).to_be_bytes::<32>();
        
        let mut result = [0u8; 32];
        let tx_bytes = tx_hash.as_slice();
        let caller_bytes = caller.as_slice();
        
        // XOR the first bytes with tx_hash
        for i in 0..32 {
            result[i] = tx_bytes[i];
        }
        
        // XOR with caller address (20 bytes)
        for i in 0..20 {
            result[i] ^= caller_bytes[i];
        }
        
        // XOR with timestamp
        for i in 0..32 {
            result[i] ^= timestamp_bytes[i];
        }
        
        FixedBytes::from(result)
    }
    
    /// Emits a dispute initiated event
    fn emit_dispute_initiated(&self, dispute_id: FixedBytes<32>, challenger: Address, defender: Address) {
        // Create topic data
        let topic0 = self.dispute_initiated_topic();
        
        // Pad addresses to 32 bytes
        let mut t2_bytes = [0u8; 32];
        t2_bytes[12..].copy_from_slice(challenger.as_slice());
        let t2 = FixedBytes::from_slice(&t2_bytes);
        
        let mut t3_bytes = [0u8; 32];
        t3_bytes[12..].copy_from_slice(defender.as_slice());
        let t3 = FixedBytes::from_slice(&t3_bytes);
        
        // Create topics array
        let topics = [topic0, dispute_id, t2, t3];
        
        // Empty data array
        let empty_data: [u8; 0] = [];
        
        // Emit the event using VM
        let _ = self.vm().raw_log(&topics, &empty_data);
    }
    
    /// Emits a dispute resolved event
    fn emit_dispute_resolved(&self, dispute_id: FixedBytes<32>) {
        // Create topic data
        let topic0 = self.dispute_resolved_topic();
        
        // Create topics array
        let topics = [topic0, dispute_id];
        
        // Empty data array
        let empty_data: [u8; 0] = [];
        
        // Emit the event using VM
        let _ = self.vm().raw_log(&topics, &empty_data);
    }
    
    /// Returns the topic hash for dispute initiated events
    fn dispute_initiated_topic(&self) -> FixedBytes<32> {
        // keccak256("DisputeInitiated(bytes32,address,address)")
        FixedBytes::from([
            0xc0, 0xff, 0xc5, 0x25, 0xa1, 0xc7, 0xed, 0x42,
            0xf5, 0x80, 0x0d, 0x34, 0x56, 0x82, 0x6e, 0x1a,
