const HISTORY_SIZE: usize = 5;

const fn pow3(exp: usize) -> usize {
    let mut result = 1;
    let mut i = 0;
    while i < exp {
        result *= 3;
        i += 1;
    }
    result
}

const Q_TABLE_SIZE: usize = pow3(HISTORY_SIZE);

