use alloc::vec::Vec;
use libbucharesthashing::{immutables::*, prover, prover::Piece};

pub type Board = Vec<(u32, Piece, u32)>;

const KING_ID: u8 = Piece::KING as u8;
const DENSE_REPRESENTATION_THRESHOLD: usize = 80;

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

fn xy_to_pos(row_size: u32, x: u32, y: u32) -> u32 {
    y.wrapping_mul(row_size).wrapping_add(x)
}

fn in_bounds(row_size: u32, x: u32, y: u32) -> bool {
    x < row_size && y < row_size
}

fn is_checking(row_size: u32, king_pos: u32, piece_pos: u32, piece: Piece) -> bool {
    let (king_x, king_y) = pos_to_xy(row_size, king_pos);
    let (piece_x, piece_y) = pos_to_xy(row_size, piece_pos);

    if king_pos == piece_pos {
        return false;
    }

    let dx = if king_x >= piece_x { king_x - piece_x } else { piece_x - king_x };
    let dy = if king_y >= piece_y { king_y - piece_y } else { piece_y - king_y };

    match piece {
        Piece::PAWN => piece_y + 1 == king_y && dx == 1,
        Piece::CASTLE => dx == 0 || dy == 0,
        Piece::QUEEN => dx == 0 || dy == 0 || dx == dy,
        Piece::BISHOP => dx == dy,
        Piece::KNIGHT => dx * dy == 2,
        Piece::KING => dx <= 1 && dy <= 1,
    }
}

fn get_diagonal(x: u32, y: u32) -> u32 {
    x.wrapping_add(y)
}

fn get_anti_diagonal(x: u32, y: u32, row_size: u32) -> u32 {
    if y <= x.wrapping_add(row_size).wrapping_sub(1) {
        x.wrapping_add(row_size).wrapping_sub(1).wrapping_sub(y)
    } else {
        0
    }
}

fn get_y_on_anti_diagonal(x: u32, anti_diag: u32, row_size: u32) -> Option<u32> {
    if anti_diag <= x.wrapping_add(row_size).wrapping_sub(1) {
        let y = x.wrapping_add(row_size).wrapping_sub(1).wrapping_sub(anti_diag);
        if y < row_size {
            return Some(y);
        }
    }
    None
}

enum BoardRepresentation {
    Sparse(Vec<(u32, Piece, u32)>, Option<(u32, u32)>),
    Dense(ThreatTracker),
}

struct ThreatTracker {
    pieces: Vec<Option<(u32, Piece)>>,
    threatened_rows: Vec<bool>,
    threatened_cols: Vec<bool>,
    threatened_diags: Vec<bool>,
    threatened_anti_diags: Vec<bool>,
    last_king: Option<(u32, u32)>,
    row_size: u32,
}

impl ThreatTracker {
    fn new(board_size: u32) -> Self {
        let row_size = board_size.isqrt();
        let diags_count = (2 * row_size - 1) as usize;
        
        ThreatTracker {
            pieces: vec![None; board_size as usize],
            threatened_rows: vec![false; row_size as usize],
            threatened_cols: vec![false; row_size as usize],
            threatened_diags: vec![false; diags_count],
            threatened_anti_diags: vec![false; diags_count],
            last_king: None,
            row_size,
        }
    }
    
    fn from_sparse(board: &Vec<(u32, Piece, u32)>, last_king: Option<(u32, u32)>, board_size: u32) -> Self {
        let mut tracker = Self::new(board_size);
        
        tracker.last_king = last_king;
        
        for &(nonce, piece, pos) in board {
            let (x, y) = pos_to_xy(tracker.row_size, pos);
            
            tracker.pieces[pos as usize] = Some((nonce, piece));
            
            if piece != Piece::KING {
                tracker.add_piece_threats(pos, x, y, nonce, piece);
            }
        }
        
        tracker
    }
    
    fn place_piece(&mut self, pos: u32, nonce: u32, piece: Piece) -> Option<(u32, u32)> {
        let (x, y) = pos_to_xy(self.row_size, pos);
        
        if let Some((old_nonce, old_piece)) = self.pieces[pos as usize] {
            self.remove_piece_threats(pos, old_nonce, old_piece);
        }
        
        self.pieces[pos as usize] = Some((nonce, piece));
        
        if piece == Piece::KING {
            self.last_king = Some((pos, nonce));
            Some((pos, nonce))
        } else {
            self.add_piece_threats(pos, x, y, nonce, piece);
            None
        }
    }
    
    fn remove_piece_threats(&mut self, pos: u32, nonce: u32, piece: Piece) {
        let (x, y) = pos_to_xy(self.row_size, pos);
        
        match piece {
            Piece::CASTLE => {
                self.update_row_threats(y);
                self.update_col_threats(x);
            },
            Piece::BISHOP => {
                let diag = get_diagonal(x, y);
                let anti_diag = get_anti_diagonal(x, y, self.row_size);
                
                self.update_diag_threats(diag);
                self.update_anti_diag_threats(anti_diag);
            },
            Piece::QUEEN => {
                self.update_row_threats(y);
                self.update_col_threats(x);
                
                let diag = get_diagonal(x, y);
                let anti_diag = get_anti_diagonal(x, y, self.row_size);
                
                self.update_diag_threats(diag);
                self.update_anti_diag_threats(anti_diag);
            },
            _ => {}
        }
    }
    
    fn update_row_threats(&mut self, y: u32) {
        let y_usize = y as usize;
        if y_usize < self.threatened_rows.len() {
            self.threatened_rows[y_usize] = false;
            
            for pos in 0..self.row_size {
                let board_pos = xy_to_pos(self.row_size, pos, y);
                if board_pos < self.pieces.len() as u32 {
                    if let Some((_, piece)) = self.pieces[board_pos as usize] {
                        if matches!(piece, Piece::CASTLE | Piece::QUEEN) {
                            self.threatened_rows[y_usize] = true;
                            break;
                        }
                    }
                }
            }
        }
    }
    
    fn update_col_threats(&mut self, x: u32) {
        let x_usize = x as usize;
        if x_usize < self.threatened_cols.len() {
            self.threatened_cols[x_usize] = false;
            
            for pos in 0..self.row_size {
                let board_pos = xy_to_pos(self.row_size, x, pos);
                if board_pos < self.pieces.len() as u32 {
                    if let Some((_, piece)) = self.pieces[board_pos as usize] {
                        if matches!(piece, Piece::CASTLE | Piece::QUEEN) {
                            self.threatened_cols[x_usize] = true;
                            break;
                        }
                    }
                }
            }
        }
    }
    
    fn update_diag_threats(&mut self, diag: u32) {
        let diag_usize = diag as usize;
        if diag_usize < self.threatened_diags.len() {
            self.threatened_diags[diag_usize] = false;
            
            for x in 0..self.row_size {
                if x <= diag {
                    let y = diag.wrapping_sub(x);
                    if y < self.row_size {
                        let pos = xy_to_pos(self.row_size, x, y);
                        if pos < self.pieces.len() as u32 {
                            if let Some((_, piece)) = self.pieces[pos as usize] {
                                if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                    self.threatened_diags[diag_usize] = true;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    
    fn update_anti_diag_threats(&mut self, anti_diag: u32) {
        let anti_diag_usize = anti_diag as usize;
        if anti_diag_usize < self.threatened_anti_diags.len() {
            self.threatened_anti_diags[anti_diag_usize] = false;
            
            for x in 0..self.row_size {
