                    self.threatened_cols[x as usize] = true;
                }
            },
            Piece::BISHOP => {
                let diag = get_diagonal(x, y) as usize;
                let anti_diag = get_anti_diagonal(x, y, self.row_size) as usize;
                
                if diag < self.threatened_diags.len() {
                    self.threatened_diags[diag] = true;
                }
                if anti_diag < self.threatened_anti_diags.len() {
                    self.threatened_anti_diags[anti_diag] = true;
                }
            },
            Piece::QUEEN => {
