            if pos < self.pieces.len() as u32 {
                if let Some((nonce, Piece::KING)) = self.pieces[pos as usize] {
                    threats.push(nonce);
                }
            }
        }
    }
}

impl BoardRepresentation {
    fn new_sparse() -> Self {
        BoardRepresentation::Sparse(Vec::new(), None)
    }
    
    fn place_piece(&mut self, starting_hash: &[u8], nonce: u32, row_size: u32) -> Option<(u32, u32)> {
        let e = prover::hash(starting_hash, nonce);
        let p_id: u8 = (e % (KING_ID as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;
        
        match self {
            BoardRepresentation::Sparse(board, last_king) => {
                board.push((nonce, p, pos));
                
                if p == Piece::KING {
                    *last_king = Some((pos, nonce));
                }
                
                if board.len() >= DENSE_REPRESENTATION_THRESHOLD {
                    *self = BoardRepresentation::Dense(
                        ThreatTracker::from_sparse(board, *last_king, BOARD_SIZE)
                    );
                }
                
                if p == Piece::KING {
                    Some((pos, nonce))
                } else {
                    None
                }
            },
            BoardRepresentation::Dense(tracker) => {
                tracker.place_piece(pos, nonce, p)
            }
        }
    }
    
    fn calculate_threats(&self, row_size: u32, threats: &mut Vec<u32>) -> Option<(u32, u32)> {
        match self {
            BoardRepresentation::Sparse(board, last_king) => {
                if let Some((king_pos, king_nonce)) = last_king {
                    threats.clear();
                    for &(nonce, piece, piece_pos) in board {
                        if nonce != *king_nonce && is_checking(row_size, *king_pos, piece_pos, piece) {
                            threats.push(nonce);
                        }
                    }
                    Some((*king_pos, *king_nonce))
                } else {
                    None
                }
            },
            BoardRepresentation::Dense(tracker) => {
                if let Some((king_pos, king_nonce)) = tracker.last_king {
                    tracker.calculate_threats(king_pos, threats);
                    Some((king_pos, king_nonce))
                } else {
                    None
                }
            }
        }
    }
}

pub fn solve(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    solve_impl(starting_hash, start)
}

fn solve_impl(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    let row_size = BOARD_SIZE.isqrt();
    
    let mut board = BoardRepresentation::new_sparse();
    
    for j in 0..start {
        board.place_piece(starting_hash, j, row_size);
    }

    let mut threats_buffer: Vec<u32> = Vec::with_capacity((CHECKS_NEEDED * 2) as usize);

    for i in start..MAX_TRIES {
        board.place_piece(starting_hash, i, row_size);

        if let Some((_, last_king_nonce)) = board.calculate_threats(row_size, &mut threats_buffer) {
            if threats_buffer.len() >= CHECKS_NEEDED as usize {
                let mut min_nonce_found = last_king_nonce;
                for &threat_nonce in &threats_buffer {
                    if threat_nonce < min_nonce_found {
                        min_nonce_found = threat_nonce;
                    }
                }

                return Some((min_nonce_found, i));
            }
        }
    }

    None
}

#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        let result = solve(hash.as_slice(), from);

        match result {
             Some(r) => Ok(r),
             None => Err(vec![])
        }
    }
}

