            }
        }
        
        // King check using lookup table
        for &(dx, dy) in &KING_MOVES {
            let other_king_x = king_x.wrapping_add_signed(dx);
            let other_king_y = king_y.wrapping_add_signed(dy);
            if in_bounds(self.row_size, other_king_x, other_king_y) {
                let packed_pos = pack_coords(other_king_x, other_king_y);
                if let Some((nonce, Piece::KING)) = self.pieces.get(&packed_pos) {
