            }
        }
        
        // Check diagonal for bishop/queen
        let diag = get_diagonal(king_x, king_y);
        if self.diags_with_sliding_pieces.contains(&diag) {
            // Scan the diagonal for threatening pieces
            for x in 0..self.row_size {
                if x != king_x && x <= diag {
                    let y = diag.wrapping_sub(x);
                    if y < self.row_size {
                        let packed_pos = pack_coords(x, y);
                        if let Some((nonce, piece)) = self.pieces.get(&packed_pos) {
                            if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                threats.push(*nonce);
                            }
                        }
                    }
                }
            }
        }
        
        // Check anti-diagonal for bishop/queen
        let anti_diag = get_anti_diagonal(king_x, king_y, self.row_size);
        if self.anti_diags_with_sliding_pieces.contains(&anti_diag) {
            // Scan the anti-diagonal for threatening pieces
            for x in 0..self.row_size {
                if x != king_x {
                    if let Some(y) = get_y_on_anti_diagonal(x, anti_diag, self.row_size) {
                        let packed_pos = pack_coords(x, y);
                        if let Some((nonce, piece)) = self.pieces.get(&packed_pos) {
                            if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                threats.push(*nonce);
                            }
                        }
                    }
                }
            }
        }
    }
    
    // Helper function to check for pawn threats
    fn check_pawn_threat(&self, x: u32, y: u32, threats: &mut Vec<u32>) {
        let packed_pos = pack_coords(x, y);
        if let Some((nonce, Piece::PAWN)) = self.pieces.get(&packed_pos) {
            threats.push(*nonce);
        }
    }
    
    // Get the current piece count
    fn len(&self) -> usize {
        self.pieces.len()
    }
}

// ==================== Hybrid Representation Tracker ====================

// Enum to represent different board representations
enum BoardRepresentation {
    // Original sparse representation: Vec of (nonce, piece, position)
    Sparse(Vec<(u32, Piece, u32)>, Option<(u32, u32)>), // Board + Last king (pos, nonce)
    
    // Optimized sparse matrix representation
    CustomSparse(SparseMatrix),
    
    // Dense representation with bit vectors
    Dense(ThreatTracker),
}

// ==================== Optimized Bit Vector for Threat Tracking ====================

// A compact structure to track which squares are threatened by which pieces
// Uses a bit vector to track which lines have threats
struct ThreatTracker {
    // Maps position -> (nonce, piece_type)
    pieces: Vec<Option<(u32, Piece)>>,
    // Bit vectors for tracking which lines are threatened
    threatened_rows: Vec<bool>,
    threatened_cols: Vec<bool>,
    threatened_diags: Vec<bool>,
    threatened_anti_diags: Vec<bool>,
    // Last king position and nonce
    last_king: Option<(u32, u32)>,
    // Board dimensions
    row_size: u32,
}

impl ThreatTracker {
    fn new(board_size: u32) -> Self {
        let row_size = board_size.isqrt();
        let diags_count = (2 * row_size - 1) as usize;
        
        ThreatTracker {
            pieces: vec![None; board_size as usize],
            threatened_rows: vec![false; row_size as usize],
            threatened_cols: vec![false; row_size as usize],
            threatened_diags: vec![false; diags_count],
            threatened_anti_diags: vec![false; diags_count],
            last_king: None,
            row_size,
        }
    }
    
    // Initialize from a sparse board representation
    fn from_sparse(board: &Vec<(u32, Piece, u32)>, last_king: Option<(u32, u32)>, board_size: u32) -> Self {
        let mut tracker = Self::new(board_size);
        
        // Copy last king info
        tracker.last_king = last_king;
        
        // Place all pieces from the sparse board
        for &(nonce, piece, pos) in board {
            let (x, y) = pos_to_xy(tracker.row_size, pos);
            
            // Update board state
            tracker.pieces[pos as usize] = Some((nonce, piece));
            
            // Update threat tracking for non-king pieces
            if piece != Piece::KING {
                tracker.add_piece_threats(pos, x, y, nonce, piece);
            }
        }
        
        tracker
    }
    
    // Place a piece on the board and update threat tracking
    fn place_piece(&mut self, pos: u32, nonce: u32, piece: Piece) -> Option<(u32, u32)> {
        let (x, y) = pos_to_xy(self.row_size, pos);
        
        // Check if replacing an existing piece
        if let Some((old_nonce, old_piece)) = self.pieces[pos as usize] {
            self.remove_piece_threats(pos, old_nonce, old_piece);
        }
        
        // Update board state
        self.pieces[pos as usize] = Some((nonce, piece));
        
        // Track king position or update threat tracking
        if piece == Piece::KING {
            self.last_king = Some((pos, nonce));
            Some((pos, nonce))
        } else {
            self.add_piece_threats(pos, x, y, nonce, piece);
            None
        }
    }
    
    // Remove piece threats when a piece is replaced
    fn remove_piece_threats(&mut self, pos: u32, nonce: u32, piece: Piece) {
        let (x, y) = pos_to_xy(self.row_size, pos);
        
        // Check if we need to update the threatened line vectors
        match piece {
            Piece::CASTLE => {
                // Check if another piece still threatens this row/column
                self.update_row_threats(y);
                self.update_col_threats(x);
            },
            Piece::BISHOP => {
                let diag = get_diagonal(x, y);
                let anti_diag = get_anti_diagonal(x, y, self.row_size);
                
                self.update_diag_threats(diag);
                self.update_anti_diag_threats(anti_diag);
            },
            Piece::QUEEN => {
                self.update_row_threats(y);
                self.update_col_threats(x);
                
                let diag = get_diagonal(x, y);
                let anti_diag = get_anti_diagonal(x, y, self.row_size);
                
                self.update_diag_threats(diag);
                self.update_anti_diag_threats(anti_diag);
            },
            _ => {} // Other pieces don''t affect threat tracking
        }
    }
    
    // Update threat vectors after removing a piece
    fn update_row_threats(&mut self, y: u32) {
        // Check if any other piece threatens this row
        let y_usize = y as usize;
        if y_usize < self.threatened_rows.len() {
            self.threatened_rows[y_usize] = false;
            
            for pos in 0..self.row_size {
                let board_pos = xy_to_pos(self.row_size, pos, y);
                if board_pos < self.pieces.len() as u32 {
                    if let Some((_, piece)) = self.pieces[board_pos as usize] {
                        if matches!(piece, Piece::CASTLE | Piece::QUEEN) {
                            self.threatened_rows[y_usize] = true;
                            break;
                        }
                    }
                }
            }
        }
    }
    
    fn update_col_threats(&mut self, x: u32) {
        let x_usize = x as usize;
        if x_usize < self.threatened_cols.len() {
            self.threatened_cols[x_usize] = false;
            
            for pos in 0..self.row_size {
                let board_pos = xy_to_pos(self.row_size, x, pos);
                if board_pos < self.pieces.len() as u32 {
                    if let Some((_, piece)) = self.pieces[board_pos as usize] {
                        if matches!(piece, Piece::CASTLE | Piece::QUEEN) {
                            self.threatened_cols[x_usize] = true;
                            break;
                        }
                    }
                }
            }
        }
    }
    
    fn update_diag_threats(&mut self, diag: u32) {
        let diag_usize = diag as usize;
        if diag_usize < self.threatened_diags.len() {
            self.threatened_diags[diag_usize] = false;
            
            // Safely check all positions on this diagonal
            for x in 0..self.row_size {
                if x <= diag {
                    let y = diag.wrapping_sub(x);
                    if y < self.row_size {
                        let pos = xy_to_pos(self.row_size, x, y);
                        if pos < self.pieces.len() as u32 {
                            if let Some((_, piece)) = self.pieces[pos as usize] {
                                if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                    self.threatened_diags[diag_usize] = true;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    
    fn update_anti_diag_threats(&mut self, anti_diag: u32) {
        let anti_diag_usize = anti_diag as usize;
        if anti_diag_usize < self.threatened_anti_diags.len() {
            self.threatened_anti_diags[anti_diag_usize] = false;
            
            // Process all positions on this anti-diagonal safely
            for x in 0..self.row_size {
                if let Some(y) = get_y_on_anti_diagonal(x, anti_diag, self.row_size) {
                    let pos = xy_to_pos(self.row_size, x, y);
                    if pos < self.pieces.len() as u32 {
                        if let Some((_, piece)) = self.pieces[pos as usize] {
                            if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                self.threatened_anti_diags[anti_diag_usize] = true;
                                break;
                            }
                        }
                    }
                }
            }
        }
    }
    
    // Add threats for a piece
    fn add_piece_threats(&mut self, pos: u32, x: u32, y: u32, nonce: u32, piece: Piece) {
        // For sliding pieces, update the threat bit vectors and tracking set
        match piece {
            Piece::CASTLE => {
                // Add rook threats for row and column
                if (y as usize) < self.threatened_rows.len() {
                    self.threatened_rows[y as usize] = true;
                }
                if (x as usize) < self.threatened_cols.len() {
                    self.threatened_cols[x as usize] = true;
                }
            },
            Piece::BISHOP => {
                // Add bishop threats for diagonals
                let diag = get_diagonal(x, y) as usize;
                let anti_diag = get_anti_diagonal(x, y, self.row_size) as usize;
                
                if diag < self.threatened_diags.len() {
                    self.threatened_diags[diag] = true;
                }
                if anti_diag < self.threatened_anti_diags.len() {
                    self.threatened_anti_diags[anti_diag] = true;
                }
            },
            Piece::QUEEN => {
                // Add queen threats for rows, columns, and diagonals
                if (y as usize) < self.threatened_rows.len() {
                    self.threatened_rows[y as usize] = true;
                }
                if (x as usize) < self.threatened_cols.len() {
                    self.threatened_cols[x as usize] = true;
                }
                
                let diag = get_diagonal(x, y) as usize;
                let anti_diag = get_anti_diagonal(x, y, self.row_size) as usize;
                
                if diag < self.threatened_diags.len() {
                    self.threatened_diags[diag] = true;
                }
                if anti_diag < self.threatened_anti_diags.len() {
                    self.threatened_anti_diags[anti_diag] = true;
                }
            },
            _ => {} // Other pieces don''t update these structures
        }
    }
    
    // Calculate all threats to a king
    fn calculate_threats(&self, king_pos: u32, threats: &mut Vec<u32>) {
        threats.clear();
        
        let (king_x, king_y) = pos_to_xy(self.row_size, king_pos);
        
        // --- Check pieces that attack specific squares around the king ---
        
        // Pawn check (relative to king, assumes king perspective needs y-1)
        if king_y > 0 {
            let check_y = king_y.wrapping_sub(1);
            // Check diagonally forward left and right
            self.check_pawn_threat(king_x.wrapping_add(1), check_y, threats);
            self.check_pawn_threat(king_x.wrapping_sub(1), check_y, threats);
        }
        
        // Knight check using lookup table
        for &(dx, dy) in &KNIGHT_MOVES {
            self.check_knight_threat(king_x, king_y, dx, dy, threats);
        }
        
        // King check (for enemy king) using lookup table
        for &(dx, dy) in &KING_MOVES {
            self.check_king_threat(king_x, king_y, dx, dy, threats);
        }
        
        // --- Check threatened lines (for sliding pieces: rook, bishop, queen) ---
        
        // Check if king''s row is threatened
        if (king_y as usize) < self.threatened_rows.len() && self.threatened_rows[king_y as usize] {
            // Find the threatening piece(s) on this row
            for x in 0..self.row_size {
                if x != king_x { // Skip king position
                    let pos = xy_to_pos(self.row_size, x, king_y);
                    if pos < self.pieces.len() as u32 {
                        if let Some((nonce, piece)) = self.pieces[pos as usize] {
                            if matches!(piece, Piece::CASTLE | Piece::QUEEN) {
                                threats.push(nonce);
                            }
                        }
                    }
                }
            }
        }
        
        // Check if king''s column is threatened
        if (king_x as usize) < self.threatened_cols.len() && self.threatened_cols[king_x as usize] {
            // Find the threatening piece(s) on this column
            for y in 0..self.row_size {
                if y != king_y { // Skip king position
                    let pos = xy_to_pos(self.row_size, king_x, y);
                    if pos < self.pieces.len() as u32 {
                        if let Some((nonce, piece)) = self.pieces[pos as usize] {
                            if matches!(piece, Piece::CASTLE | Piece::QUEEN) {
                                threats.push(nonce);
                            }
                        }
                    }
                }
            }
        }
        
        // Check if king''s diagonal is threatened
        let diag = get_diagonal(king_x, king_y) as usize;
        if diag < self.threatened_diags.len() && self.threatened_diags[diag] {
            // Find the threatening piece(s) on this diagonal
            for x in 0..self.row_size {
                if x != king_x && x <= diag as u32 { // Skip king position and ensure valid calculation
                    let y = (diag as u32).wrapping_sub(x);
                    if y < self.row_size {
                        let pos = xy_to_pos(self.row_size, x, y);
                        if pos < self.pieces.len() as u32 {
                            if let Some((nonce, piece)) = self.pieces[pos as usize] {
                                if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                    threats.push(nonce);
                                }
                            }
                        }
                    }
                }
            }
        }
        
        // Check if king''s anti-diagonal is threatened
        let anti_diag = get_anti_diagonal(king_x, king_y, self.row_size) as usize;
        if anti_diag < self.threatened_anti_diags.len() && self.threatened_anti_diags[anti_diag] {
            // Find the threatening piece(s) on this anti-diagonal safely
            for x in 0..self.row_size {
                if x != king_x { // Skip king position
                    if let Some(y) = get_y_on_anti_diagonal(x, anti_diag as u32, self.row_size) {
                        let pos = xy_to_pos(self.row_size, x, y);
                        if pos < self.pieces.len() as u32 {
                            if let Some((nonce, piece)) = self.pieces[pos as usize] {
                                if matches!(piece, Piece::BISHOP | Piece::QUEEN) {
                                    threats.push(nonce);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    
    // Helper functions for checking specific piece threats
    fn check_pawn_threat(&self, x: u32, y: u32, threats: &mut Vec<u32>) {
        if in_bounds(self.row_size, x, y) {
            let pos = xy_to_pos(self.row_size, x, y);
            if pos < self.pieces.len() as u32 {
                if let Some((nonce, Piece::PAWN)) = self.pieces[pos as usize] {
                    threats.push(nonce);
                }
            }
        }
    }
    
    fn check_knight_threat(&self, king_x: u32, king_y: u32, dx: i32, dy: i32, threats: &mut Vec<u32>) {
        let check_x = king_x.wrapping_add_signed(dx);
        let check_y = king_y.wrapping_add_signed(dy);
        if in_bounds(self.row_size, check_x, check_y) {
            let pos = xy_to_pos(self.row_size, check_x, check_y);
            if pos < self.pieces.len() as u32 {
                if let Some((nonce, Piece::KNIGHT)) = self.pieces[pos as usize] {
                    threats.push(nonce);
                }
            }
        }
    }
    
    fn check_king_threat(&self, king_x: u32, king_y: u32, dx: i32, dy: i32, threats: &mut Vec<u32>) {
        let check_x = king_x.wrapping_add_signed(dx);
        let check_y = king_y.wrapping_add_signed(dy);
        if in_bounds(self.row_size, check_x, check_y) {
            let pos = xy_to_pos(self.row_size, check_x, check_y);
            if pos < self.pieces.len() as u32 {
                if let Some((nonce, Piece::KING)) = self.pieces[pos as usize] {
                    threats.push(nonce);
                }
            }
        }
    }
}

impl BoardRepresentation {
    // Create a new board representation
    fn new_sparse() -> Self {
        // Start with the optimized custom sparse matrix
        BoardRepresentation::CustomSparse(SparseMatrix::new(BOARD_SIZE))
    }
    
    // Place a piece on the board, potentially converting between representations
    fn place_piece(&mut self, starting_hash: &[u8], nonce: u32, row_size: u32) -> Option<(u32, u32)> {
        let e = prover::hash(starting_hash, nonce);
        let p_id: u8 = (e % (KING_ID as u64 + 1)).try_into().unwrap();
        let p = Piece::try_from(p_id).unwrap();
        let offset: u32 = (e >> 32).try_into().unwrap();
        let pos: u32 = offset % BOARD_SIZE;

        match self {
            BoardRepresentation::Sparse(board, last_king) => {
                // Add piece to the sparse board
                board.push((nonce, p, pos));
                
                // Update last king if needed
                if p == Piece::KING {
                    *last_king = Some((pos, nonce));
                }
                
                // Check if we need to convert to dense representation
                if board.len() >= DENSE_REPRESENTATION_THRESHOLD {
                    // Convert to dense representation
                    *self = BoardRepresentation::Dense(
                        ThreatTracker::from_sparse(board, *last_king, BOARD_SIZE)
                    );
                }
                
                // Return last king info if this was a king placement
                if p == Piece::KING {
                    Some((pos, nonce))
                } else {
                    None
                }
            },
            BoardRepresentation::CustomSparse(matrix) => {
                // Add piece to custom sparse matrix
                let king_info = matrix.place_piece(pos, nonce, p);
                
                // Check if we need to convert to dense representation
                if matrix.len() >= DENSE_REPRESENTATION_THRESHOLD {
                    // Convert to dense representation by first getting all pieces
                    let mut pieces = Vec::with_capacity(matrix.len());
                    let king_position = matrix.king_position;
                    
                    // Manually build a list of pieces from the sparse matrix
                    for (&packed_pos, &(piece_nonce, piece_type)) in &matrix.pieces {
                        let (x, y) = unpack_coords(packed_pos);
                        let pos = xy_to_pos(row_size, x, y);
                        pieces.push((piece_nonce, piece_type, pos));
                    }
                    
                    // Convert to dense representation
                    *self = BoardRepresentation::Dense(
                        ThreatTracker::from_sparse(&pieces, king_position, BOARD_SIZE)
                    );
                }
                
                king_info
            },
            BoardRepresentation::Dense(tracker) => {
                // Place piece using the dense tracker
                tracker.place_piece(pos, nonce, p)
            }
        }
    }
    
    // Calculate threats to the king
    fn calculate_threats(&self, row_size: u32, threats: &mut Vec<u32>) -> Option<(u32, u32)> {
        match self {
            BoardRepresentation::Sparse(board, last_king) => {
                if let Some((king_pos, king_nonce)) = last_king {
                    // Calculate threats using the sparse approach
                    threats.clear();
                    for &(nonce, piece, piece_pos) in board {
                        if nonce != *king_nonce && is_checking(row_size, *king_pos, piece_pos, piece) {
                            threats.push(nonce);
                        }
                    }
                    Some((*king_pos, *king_nonce))
                } else {
                    None
                }
            },
            BoardRepresentation::CustomSparse(matrix) => {
                if let Some((king_pos, king_nonce)) = matrix.king_position {
                    // Calculate threats using the optimized sparse approach
                    matrix.calculate_threats(king_pos, threats);
                    Some((king_pos, king_nonce))
                } else {
                    None
                }
            },
            BoardRepresentation::Dense(tracker) => {
                if let Some((king_pos, king_nonce)) = tracker.last_king {
                    // Calculate threats using the optimized approach
                    tracker.calculate_threats(king_pos, threats);
                    Some((king_pos, king_nonce))
                } else {
                    None
                }
            }
        }
    }
}

// ==================== Main Algorithm Functions ====================

pub fn solve(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    solve_impl(starting_hash, start)
}

fn solve_impl(starting_hash: &[u8], start: u32) -> Option<(u32, u32)> {
    // Pre-compute row_size once
    let row_size = BOARD_SIZE.isqrt();
    
    // Start with sparse representation
    let mut board = BoardRepresentation::new_sparse();
    
    // Initialization loop - place pieces from 0 to start
    for j in 0..start {
        board.place_piece(starting_hash, j, row_size);
    }

    // Pre-allocate threats buffer
    let mut threats_buffer: Vec<u32> = Vec::with_capacity((CHECKS_NEEDED * 2) as usize);

    // Main loop
    for i in start..MAX_TRIES {
        // Place piece (might convert to dense representation if threshold reached)
        board.place_piece(starting_hash, i, row_size);

        // Calculate threats if there''s a king
        if let Some((_, last_king_nonce)) = board.calculate_threats(row_size, &mut threats_buffer) {
            if threats_buffer.len() >= CHECKS_NEEDED as usize {
                // Find the minimum nonce among threats
                let mut min_nonce_found = last_king_nonce;
                for &threat_nonce in &threats_buffer {
                    if threat_nonce < min_nonce_found {
                        min_nonce_found = threat_nonce;
                    }
                }

                return Some((min_nonce_found, i));
            }
        }
    }

    None
}

// ==================== Smart Contract Interface ====================

#[storage]
#[entrypoint]
pub struct Storage {}

#[public]
impl Storage {
    pub fn prove(&self, hash: FixedBytes<32>, from: u32) -> Result<(u32, u32), Vec<u8>> {
        let result = solve(hash.as_slice(), from);

        match result {
             Some(r) => Ok(r),
             None => Err(vec![])
        }
    }
}

// ==================== Tests ====================

#[cfg(all(test, not(target_arch = "wasm32")))]
mod test {
    use super::*;
    use proptest::prelude::*;
    use libbucharesthashing::prover;

    proptest! {
        #![proptest_config(ProptestConfig { cases: 5000, ..Default::default() })]
        #[test]
        fn test_solve(starting_hash in prop::array::uniform32(any::<u8>())) {
            
            if let Some((e_l, e_h)) = solve(&starting_hash, 0) {
                
                if let Some((t_l, t_h)) = solve(&starting_hash, e_l) {
                   assert_eq!((e_l, e_h), (t_l, t_h), "user contract not consistent. {e_l} != {t_l} or {e_h} != {t_h}");
                } else {
                   panic!("Second solve failed where first succeeded");
                }

                if let Some((p_l, p_h)) = prover::default_solve(&starting_hash, e_l) {
                     assert_eq!(
                        (e_l, e_h), (p_l, p_h),
                        "user contract inconsistent with reference. solve(0) -> ({e_l}, {e_h}) but prover::solve({e_l}) -> ({p_l}, {p_h})"
                     );
                } else {
                     panic!("Reference solve failed starting from {e_l} where user solve succeeded from 0 finding ({e_l}, {e_h})");
                }

                 if let Some((p0_l, p0_h)) = prover::default_solve(&starting_hash, 0) {
                     assert_eq!(
                         (e_l, e_h), (p0_l, p0_h),
                         "user contract inconsistent with reference starting at 0. user: ({e_l}, {e_h}), prover: ({p0_l}, {p0_h})"
                     );
                 } else {
                      panic!("Reference solve failed starting from 0 where user solve succeeded finding ({e_l}, {e_h})");
                 }


            } else {
                 if let Some((p0_l, p0_h)) = prover::default_solve(&starting_hash, 0) {
                     panic!("User solve failed from 0 but reference solve succeeded finding ({p0_l}, {p0_h})");
                 }
            }
