use stylus_sdk::{alloy_primitives::*, prelude::*};

use alloc::{vec, vec::Vec};

use libbucharesthashing::{immutables::*, prover, prover::Piece};

/* ~~~~~~~~~~~~~~ BOARD IMPLEMENTATION ~~~~~~~~~~~~~~ */

/// Using a more gas-efficient representation for the board
/// Fixed-size capacity for small boards is more gas efficient
type Board = Vec<(u32, Piece, u32)>;

fn pos_to_xy(row_size: u32, p: u32) -> (u32, u32) {
    (p % row_size, p / row_size)
}

// Find the in check threats for the king given, returning the nonces of
// the threats.
fn in_check_threats(board: &Board, row_size: u32, king_pos: u32) -> Vec<u32> {
    let (king_x, king_y) = pos_to_xy(row_size, king_pos);
    let mut threats = Vec::with_capacity(8);
    
    for &(pos, piece, nonce) in board {
        // Skip the king itself
        if pos == king_pos {
            continue;
        }
        
        let (piece_x, piece_y) = pos_to_xy(row_size, pos);
        
        // Fast path threat detection based on piece type
        match piece {
            Piece::PAWN => {
                // Pawns attack diagonally forward
                if piece_y + 1 == king_y && (piece_x + 1 == king_x || king_x + 1 == piece_x) {
                    threats.push(nonce);
                }
            },
            
            Piece::KNIGHT => {
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                // Knight L shape: (1,2) or (2,1)
                if (dx == 1 && dy == 2) || (dx == 2 && dy == 1) {
                    threats.push(nonce);
                }
            },
            
            Piece::CASTLE => {
                // Rooks move horizontally or vertically
                if (piece_x == king_x || piece_y == king_y) && is_clear_path(board, piece_x, piece_y, king_x, king_y) {
                    threats.push(nonce);
                }
            },
            
            Piece::BISHOP => {
                // Bishops move diagonally
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                if dx == dy && is_clear_path(board, piece_x, piece_y, king_x, king_y) {
                    threats.push(nonce);
                }
            },
            
            Piece::QUEEN => {
                // Queens combine rook and bishop movement
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                
                // Horizontal/vertical (rook-like) or diagonal (bishop-like)
                if ((piece_x == king_x || piece_y == king_y) || dx == dy) && 
                   is_clear_path(board, piece_x, piece_y, king_x, king_y) {
                    threats.push(nonce);
                }
            },
            
            Piece::KING => {
                // Kings threaten adjacent squares
                let dx = if piece_x > king_x { piece_x - king_x } else { king_x - piece_x };
                let dy = if piece_y > king_y { piece_y - king_y } else { king_y - piece_y };
                
                // One square in any direction
                if dx <= 1 && dy <= 1 && (dx > 0 || dy > 0) {
                    threats.push(nonce);
                }
            },
        }
    }
    
    threats
}

// Check if there are no pieces between source and destination
fn is_clear_path(board: &Board, src_x: u32, src_y: u32, dst_x: u32, dst_y: u32) -> bool {
    // Same position
    if src_x == dst_x && src_y == dst_y {
        return true;
    }
    
    let row_size = BOARD_SIZE.isqrt();
    
    // Determine step direction
    let dx = if src_x < dst_x { 1i32 } else if src_x > dst_x { -1i32 } else { 0i32 };
    let dy = if src_y < dst_y { 1i32 } else if src_y > dst_y { -1i32 } else { 0i32 };
    
    let mut x = src_x as i32 + dx;
    let mut y = src_y as i32 + dy;
    
    // Check each position along the path
    while (x as u32 != dst_x || y as u32 != dst_y) && x >= 0 && y >= 0 && (x as u32) < row_size && (y as u32) < row_size {
        let check_pos = (y as u32) * row_size + (x as u32);
        
        // Check if any piece is at this position
        for &(pos, _, _) in board {
            if pos == check_pos {
                return false; // Path is blocked
            }
        }
        
        // Move to next position
        x += dx;
        y += dy;
    }
    
    true // Path is clear
}

